<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>足控天堂 Ⅱ · 虚拟主播事务所</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Quicksand:wght@500;600;700&family=M+PLUS+Rounded+1c:wght@500;700;800&display=swap');

:root{
  --cyan:#49b8dd;
  --cyan-2:#8fdcf2;
  --cyan-soft:#e4f6fd;
  --pink:#ff7fb2;
  --pink-2:#ffa8cd;
  --pink-soft:#ffe9f3;
  --hot:#ff5f9e;
  --lemon:#ffd76e;
  --ink:#28495c;
  --ink-2:#7fa1b3;
  --ink-3:#a8c2cf;
  --card:#ffffff;
  --line:#cfe9f4;
  --line-2:#b7dfef;
  --r:20px;
  --r-sm:14px;
  --pill:999px;
  --mono:ui-monospace,"SFMono-Regular",Consolas,monospace;
  --round:'M PLUS Rounded 1c','Quicksand',-apple-system,"PingFang SC","Microsoft YaHei",sans-serif;
  --soft:0 10px 26px rgba(73,184,221,.14);
  --soft-p:0 10px 26px rgba(255,127,178,.18);
}
*{margin:0;padding:0;box-sizing:border-box}
body{
  background:linear-gradient(160deg,#ddf2fb 0%,#eaf7fd 42%,#fdeef6 100%);
  color:var(--ink);
  font:500 15px/1.8 var(--round);
  -webkit-font-smoothing:antialiased;overflow-x:hidden;overflow-y:auto;
}
h1,h2,h3{font-weight:800;letter-spacing:.02em}
button,input,select,textarea{font-family:inherit;font-size:inherit;color:inherit}
::selection{background:rgba(255,127,178,.3)}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:var(--line-2);border-radius:99px}
::-webkit-scrollbar-track{background:transparent}

/* ══════════ 全屏封面 · INS 杂志风 ══════════ */
#coverPage{
  position:relative;z-index:200;
  overflow:hidden;
  transition:opacity .6s ease;
}
/* 底纹：软青粉渐变 + 涂鸦 */
.ins-bg{position:absolute;inset:0;z-index:0;pointer-events:none;
  background:
    radial-gradient(680px 420px at 8% 4%,rgba(143,220,242,.5),transparent 62%),
    radial-gradient(720px 460px at 96% 90%,rgba(255,168,205,.42),transparent 60%),
    radial-gradient(420px 300px at 88% 8%,rgba(255,215,110,.24),transparent 60%),
    linear-gradient(160deg,#ddf2fb 0%,#eaf7fd 42%,#fdeef6 100%)}
.ins-bg::before{content:'';position:absolute;inset:0;opacity:.5;
  background-image:
    radial-gradient(circle,rgba(73,184,221,.16) 1.6px,transparent 1.8px),
    radial-gradient(circle,rgba(255,127,178,.14) 1.4px,transparent 1.6px);
  background-size:120px 120px,170px 150px;background-position:14px 20px,80px 90px}
.ins-doodles{position:absolute;inset:0;z-index:0;pointer-events:none;font-size:26px;opacity:.34}
.ins-doodles span{position:absolute;filter:saturate(.8)}
.d1{top:7%;left:4%;transform:rotate(-14deg)}
.d2{top:16%;right:6%;transform:rotate(12deg)}
.d3{top:58%;left:2.5%;transform:rotate(8deg)}
.d4{top:44%;right:3%;transform:rotate(-10deg)}
.d5{bottom:8%;left:8%;transform:rotate(-6deg)}
.d6{bottom:16%;right:9%;transform:rotate(14deg)}

.ins-wrap{position:relative;z-index:1;max-width:620px;margin:0 auto;
  padding:18px 16px 30px;display:flex;flex-direction:column;gap:16px}

/* 顶部拟 App 栏 */
.ins-topbar{display:flex;align-items:center;gap:10px}
.tb-menu{width:44px;height:40px;flex:0 0 44px;border-radius:14px;background:var(--card);
  border:2px solid var(--cyan);box-shadow:var(--soft);display:flex;flex-direction:column;
  align-items:flex-start;justify-content:center;gap:4px;padding:0 10px;cursor:pointer}
.tb-menu i{display:block;height:2.6px;border-radius:2px;background:var(--cyan)}
.tb-menu i:nth-child(1){width:70%}.tb-menu i:nth-child(2){width:100%}.tb-menu i:nth-child(3){width:50%}
.tb-search{flex:1;height:40px;border-radius:var(--pill);background:rgba(255,255,255,.75);
  border:2px solid var(--cyan-2);display:flex;align-items:center;gap:8px;padding:0 18px;
  font:600 13px/1 var(--round);color:var(--ink-2);letter-spacing:.14em;overflow:hidden;white-space:nowrap}
.tb-foryou{height:40px;padding:0 20px;border-radius:var(--pill);background:var(--card);
  border:2px solid var(--pink);color:var(--pink);font:700 13px/1 var(--round);
  display:flex;align-items:center;box-shadow:var(--soft-p);white-space:nowrap}

/* 杂志主卡：对角线切割 */
.hero-card{position:relative;background:var(--card);border-radius:28px;
  border:2.5px solid rgba(73,184,221,.55);box-shadow:0 22px 54px rgba(73,184,221,.24);
  overflow:hidden;animation:heroIn .6s cubic-bezier(.34,1.3,.5,1)}
@keyframes heroIn{from{transform:translateY(24px) scale(.97);opacity:0}to{transform:none;opacity:1}}
.hero-photo{position:relative;height:340px;background:linear-gradient(140deg,var(--cyan-soft),var(--pink-soft));overflow:hidden}
.hero-photo img,.hero-photo video{width:100%;height:100%;object-fit:cover;object-position:center top;display:block;
  -webkit-user-drag:none;user-select:none;background:#0d1727}
.hero-photo::after{content:'';position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 62%,rgba(255,255,255,.9) 96%)}
.hero-kana{position:absolute;top:14px;left:16px;z-index:2;transform:rotate(-4deg);
  font:800 17px/1 var(--round);color:#fff;letter-spacing:.18em;
  text-shadow:0 2px 10px rgba(73,184,221,.65)}
.hero-bubble{position:absolute;top:18px;right:18px;z-index:2;background:#fff;
  border:2px solid var(--pink);color:var(--pink);border-radius:16px 16px 16px 4px;
  padding:7px 14px;font:800 13px/1 var(--round);transform:rotate(3deg);
  box-shadow:0 6px 16px rgba(255,127,178,.3)}
.hero-tape{position:absolute;bottom:12px;left:50%;transform:translateX(-50%) rotate(-2deg);z-index:2;
  width:130px;height:26px;background:rgba(255,168,205,.75);border:1.5px dashed rgba(255,255,255,.9);border-radius:4px}
/* 斜切白带（参考杂志的白色对角线） */
.hero-slash{position:absolute;left:-8%;right:-8%;bottom:88px;height:34px;z-index:2;
  background:#fff;transform:rotate(-7deg);box-shadow:0 6px 18px rgba(73,184,221,.18)}

.hero-panel{position:relative;padding:16px 22px 22px;background:var(--card)}
.hero-vol{position:absolute;top:-13px;right:20px;background:linear-gradient(100deg,var(--cyan),var(--cyan-2));
  color:#fff;font:800 11px/1 var(--mono);letter-spacing:.2em;padding:7px 14px;border-radius:var(--pill);
  box-shadow:0 6px 14px rgba(73,184,221,.35);transform:rotate(2deg)}
.hero-title{font-size:clamp(34px,7.5vw,46px);line-height:1.12;letter-spacing:.03em;
  background:linear-gradient(100deg,var(--hot) 10%,var(--pink) 40%,var(--cyan) 90%);
  -webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;
  filter:drop-shadow(0 3px 10px rgba(255,127,178,.28))}
.hero-title small{font-size:.52em;vertical-align:.32em;letter-spacing:.1em}
.hero-en{margin-top:4px;font:700 10.5px/1.6 var(--mono);letter-spacing:.3em;color:var(--ink-2)}
.profile-block{margin-top:14px;position:relative;padding:13px 16px;border-radius:18px;
  background:linear-gradient(120deg,var(--cyan-soft),var(--pink-soft));border:1.5px solid rgba(143,220,242,.6)}
.profile-block b{position:absolute;top:-11px;left:14px;background:var(--pink);color:#fff;
  font:800 11px/1 var(--round);letter-spacing:.14em;padding:5px 13px;border-radius:var(--pill);
  box-shadow:0 4px 10px rgba(255,127,178,.32);transform:rotate(-2deg)}
.profile-block p{margin-top:6px;font-size:13px;line-height:1.9;color:var(--ink);
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.profile-block p b{position:static;background:none;padding:0;box-shadow:none;transform:none;
  color:var(--hot);font-size:13px;letter-spacing:0}
.hero-stats{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}
.chip{padding:6px 14px;border-radius:var(--pill);font:700 11.5px/1 var(--mono);letter-spacing:.08em;
  background:#fff;border:1.6px solid var(--line-2);color:var(--ink-2)}
.chip.pink{background:var(--pink-soft);border-color:var(--pink-2);color:var(--hot)}
.chip.cyan{background:var(--cyan-soft);border-color:var(--cyan-2);color:var(--cyan)}
.chip.lemon{background:#fff8e2;border-color:#ffd76e;color:#c99a1b}
.hero-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px}
.hero-deco{position:absolute;right:14px;bottom:12px;font-size:20px;opacity:.5;letter-spacing:6px}

/* 按钮 */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;
  padding:13px 26px;border:0;border-radius:var(--pill);cursor:pointer;
  font:800 14px/1 var(--round);letter-spacing:.06em;
  transition:transform .16s,box-shadow .16s,filter .16s,background .16s,color .16s}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(0)}
.btn-main{background:linear-gradient(100deg,var(--hot),var(--pink-2));color:#fff;
  box-shadow:0 8px 22px rgba(255,95,158,.4)}
.btn-main:hover{box-shadow:0 12px 28px rgba(255,95,158,.52)}
.btn-mint{background:linear-gradient(100deg,var(--cyan),var(--cyan-2));color:#fff;
  box-shadow:0 8px 22px rgba(73,184,221,.38)}
.btn-mint:hover{box-shadow:0 12px 28px rgba(73,184,221,.5)}
.btn-soft{background:#fff;color:var(--ink-2);border:1.6px solid var(--line-2)}
.btn-soft:hover{background:var(--cyan-soft);color:var(--cyan)}

/* PV 播放器卡片（杂志内嵌 PV） */
.pv-card{background:var(--card);border-radius:24px;border:2px solid rgba(255,168,205,.55);
  box-shadow:var(--soft-p);overflow:hidden}
.pv-head{display:flex;align-items:center;gap:10px;padding:12px 18px 0}
.pv-head b{font:800 12px/1 var(--mono);letter-spacing:.22em;color:var(--pink)}
.pv-head em{margin-left:auto;font:700 10px/1 var(--mono);letter-spacing:.16em;color:var(--ink-3);font-style:normal}
.pv-card video{width:100%;display:block;margin-top:10px;background:#0b1622;max-height:300px;object-fit:cover}

/* 电台小卡（参考音乐播放器） */
.fm-card{display:flex;align-items:center;gap:14px;background:var(--card);border-radius:22px;
  border:2px solid var(--line);padding:14px 18px;box-shadow:var(--soft)}
.fm-cover{width:52px;height:52px;flex:0 0 52px;border-radius:16px;display:flex;align-items:center;justify-content:center;
  font-size:24px;background:linear-gradient(140deg,var(--pink-soft),var(--cyan-soft));
  border:1.6px solid var(--line-2)}
.fm-info{flex:1;min-width:0}
.fm-t{font:800 13.5px/1.4 var(--round);color:var(--ink)}
.fm-q{margin-top:2px;font:600 11.5px/1.5 var(--round);color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fm-bar{margin-top:8px;height:7px;border-radius:99px;background:var(--cyan-soft);overflow:hidden;position:relative}
.fm-bar i{position:absolute;left:0;top:0;bottom:0;width:28%;border-radius:99px;
  background:linear-gradient(90deg,var(--pink),var(--cyan));animation:fmSlide 9s linear infinite}
@keyframes fmSlide{from{width:8%}to{width:92%}}
.fm-time{display:flex;justify-content:space-between;font:700 10px/1 var(--mono);color:var(--ink-3);margin-top:5px}
.fm-heart{font-size:20px;color:var(--hot);animation:beat 1.1s ease-in-out infinite}
@keyframes beat{0%,100%{transform:scale(1)}30%{transform:scale(1.22)}55%{transform:scale(.96)}}

/* 拼贴照片墙 */
.collage{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.polaroid{position:relative;border-radius:18px;overflow:hidden;background:#fff;
  border:2.5px solid #fff;box-shadow:0 10px 24px rgba(73,184,221,.2);
  aspect-ratio:1/1;transition:transform .2s}
.polaroid:nth-child(odd){transform:rotate(-1.6deg)}
.polaroid:nth-child(even){transform:rotate(1.4deg)}
.polaroid:hover{transform:rotate(0) translateY(-4px);z-index:2}
.polaroid img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;-webkit-user-drag:none}
.pol-face{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:44px}
.polaroid span{position:absolute;left:8px;bottom:8px;z-index:2;background:rgba(255,255,255,.88);
  color:var(--ink);font:800 10.5px/1 var(--round);padding:4px 10px;border-radius:var(--pill);
  border:1.4px solid var(--pink-2);color:var(--hot)}
.polaroid.pink{border-color:var(--pink-2)}
.polaroid.cyan{border-color:var(--cyan-2)}
.collage-note{grid-column:1/-1;display:flex;align-items:center;justify-content:center;gap:8px;
  font:700 11px/1 var(--mono);letter-spacing:.22em;color:var(--ink-3);padding:6px 0 0}

.ins-footer{text-align:center;font:700 10.5px/1.8 var(--mono);letter-spacing:.24em;color:var(--ink-3);padding-top:4px}

/* ══════════ 主界面 ══════════ */
#app{display:none;grid-template-columns:250px 1fr;min-height:100vh}
.side{border-right:2px solid var(--line);background:rgba(255,255,255,.82);backdrop-filter:blur(8px);
  display:flex;flex-direction:column;padding:18px 14px}
.brand{display:flex;align-items:center;gap:11px;padding:6px 8px 16px}
.brand-logo{width:42px;height:42px;flex:0 0 42px;border-radius:50%;
  background:linear-gradient(135deg,var(--pink),var(--cyan-2));
  display:flex;align-items:center;justify-content:center;font-size:19px;color:#fff;
  box-shadow:0 4px 14px rgba(255,127,178,.35)}
.brand-name{font-size:15px;font-weight:800;letter-spacing:.04em;color:var(--ink)}
.brand-sub{font:600 9.5px/1.5 var(--mono);letter-spacing:.16em;color:var(--ink-3)}
.nav{display:flex;flex-direction:column;gap:6px;flex:1}
.nav-cap{font:700 10px/1 var(--mono);letter-spacing:.24em;color:var(--ink-3);padding:8px 12px 4px}
.nav-item{display:flex;align-items:center;gap:10px;width:100%;text-align:left;
  padding:11px 14px;border:0;border-radius:var(--pill);background:transparent;
  color:var(--ink-2);cursor:pointer;font:700 14px/1 var(--round);letter-spacing:.04em;
  transition:background .16s,color .16s,box-shadow .16s}
.nav-item i{width:22px;height:22px;flex:0 0 22px;border-radius:50%;
  background:var(--cyan-soft);display:flex;align-items:center;justify-content:center;
  font:700 10px/1 var(--mono);font-style:normal;color:var(--cyan);transition:background .16s,color .16s}
.nav-item:hover{background:var(--cyan-soft);color:var(--cyan)}
.nav-item.on{background:linear-gradient(100deg,var(--hot),var(--pink-2));color:#fff;
  box-shadow:0 6px 16px rgba(255,95,158,.35)}
.nav-item.on i{background:rgba(255,255,255,.35);color:#fff}
.side-box{margin-top:12px;padding:14px;border-radius:var(--r-sm);
  background:linear-gradient(140deg,var(--cyan-soft),var(--pink-soft));border:1.5px solid var(--line)}
.side-box h4{font:700 10px/1 var(--mono);letter-spacing:.2em;color:var(--ink-3);margin-bottom:10px}
.sm{display:flex;align-items:center;justify-content:space-between;padding:4px 0;font-size:12.5px}
.sm span{color:var(--ink-2)}
.sm b{font:800 13px/1 var(--mono)}
.sm b.hot{color:var(--hot)} .sm b.lemon{color:#c99a1b} .sm b.mint{color:var(--cyan)}

.main{display:flex;flex-direction:column;position:relative;min-width:0}
.topbar{flex:0 0 auto;padding:15px 24px;border-bottom:2px solid var(--line);
  background:rgba(255,255,255,.82);backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:space-between;gap:14px}
.topbar h2{font-size:17px;color:var(--ink)}
.topbar .crumb{font:700 10.5px/1 var(--mono);letter-spacing:.18em;color:var(--ink-3)}
.progress{height:6px;background:var(--cyan-soft);flex:0 0 auto}
.progress i{display:block;height:100%;width:0;border-radius:0 99px 99px 0;
  background:linear-gradient(90deg,var(--pink),var(--cyan));transition:width .5s ease}
.viewport{padding:22px 22px 108px}
.view{display:none;max-width:1080px;margin:0 auto}
.view.on{display:block}

/* 底部三按钮 */
.nav-buttons{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);
  display:flex;gap:10px;z-index:120;max-width:94vw}
.nav-btn{padding:12px 24px;border-radius:var(--pill);border:0;cursor:pointer;
  font:800 13px/1 var(--round);letter-spacing:.06em;white-space:nowrap;
  transition:transform .16s,box-shadow .16s,background .16s,color .16s}
.nav-btn:hover{transform:translateY(-2px)}
.nav-btn:active{transform:translateY(0)}
.nav-prev{background:#fff;color:var(--ink-2);border:1.6px solid var(--line-2)}
.nav-prev:hover{background:var(--cyan-soft);color:var(--cyan)}
.nav-next{background:linear-gradient(100deg,var(--hot),var(--pink-2));color:#fff;
  box-shadow:0 8px 20px rgba(255,95,158,.36)}
.nav-next:hover{box-shadow:0 12px 26px rgba(255,95,158,.5)}
.nav-home{background:#fff;color:var(--cyan);border:1.6px solid var(--cyan-2)}
.nav-home:hover{background:var(--cyan-soft)}

/* 面板 */
.panel{border:1.6px solid var(--line);border-radius:var(--r);background:var(--card);box-shadow:var(--soft)}
.panel + .panel{margin-top:18px}
.panel-hd{display:flex;align-items:center;gap:10px;padding:14px 18px;
  border-bottom:1.6px solid var(--line);background:linear-gradient(100deg,var(--cyan-soft),var(--pink-soft));
  border-radius:calc(var(--r) - 1.5px) calc(var(--r) - 1.5px) 0 0}
.panel-hd .dot{width:8px;height:8px;border-radius:50%;background:var(--pink);
  box-shadow:0 0 10px rgba(255,127,178,.8)}
.panel-hd h3{font:800 11px/1 var(--mono);letter-spacing:.22em;color:var(--cyan)}
.panel-hd em{margin-left:auto;font:700 10.5px/1 var(--mono);color:var(--ink-3);font-style:normal}
.panel-bd{padding:18px}

/* KPI */
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.kpi{border:1.6px solid var(--line);border-radius:var(--r);background:var(--card);
  padding:16px;box-shadow:var(--soft);transition:transform .16s,border-color .16s}
.kpi:hover{transform:translateY(-3px);border-color:var(--pink-2)}
.kpi-top{display:flex;align-items:center;gap:9px}
.kpi-ico{width:30px;height:30px;flex:0 0 30px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;font-size:15px;
  background:var(--pink-soft)}
.kpi-k{font:700 10px/1 var(--mono);letter-spacing:.16em;color:var(--ink-3)}
.kpi-v{margin-top:11px;font:800 25px/1 var(--mono)}
.kpi-v.hot{color:var(--hot)} .kpi-v.lemon{color:#c99a1b} .kpi-v.mint{color:var(--cyan)}
.kpi-n{margin-top:7px;font-size:11.5px;color:var(--ink-2);line-height:1.6}
.bar{margin-top:10px;height:6px;border-radius:99px;background:var(--cyan-soft);overflow:hidden}
.bar i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,var(--cyan),var(--cyan-2))}
.bar.risk i{background:linear-gradient(90deg,var(--lemon),var(--hot))}
.bar.money i{background:linear-gradient(90deg,var(--lemon),var(--pink))}

.prose{font-size:14.5px;line-height:2;color:#3d6377}
.prose p + p{margin-top:13px}
.prose b{color:var(--ink)}
.prose .hi{color:var(--cyan)} .prose .wh{color:var(--hot)}

.flow{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}
.step{border:1.6px solid var(--line);border-radius:var(--r-sm);background:linear-gradient(150deg,var(--cyan-soft),#fff 70%);
  padding:14px 13px;transition:transform .16s,border-color .16s}
.step:hover{transform:translateY(-3px);border-color:var(--cyan)}
.step-n{width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(135deg,var(--cyan),var(--pink-2));color:#fff;font:800 11px/1 var(--mono)}
.step-t{margin-top:10px;font-size:13.5px;font-weight:800;color:var(--ink)}
.step-d{margin-top:5px;font-size:11.5px;line-height:1.75;color:var(--ink-2)}

.tbl-wrap{border:1.6px solid var(--line);border-radius:var(--r-sm);overflow:hidden}
.tbl{width:100%;border-collapse:collapse;font-size:13.5px}
.tbl th,.tbl td{text-align:left;padding:12px 14px;border-bottom:1px solid var(--line);vertical-align:top}
.tbl th{font:700 10px/1 var(--mono);letter-spacing:.18em;color:var(--ink-3);background:var(--cyan-soft)}
.tbl td:first-child{font-weight:800;color:var(--hot);white-space:nowrap}
.tbl tr:last-child td{border-bottom:0}
.tbl .weak{color:var(--ink-3)}

.filters{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}
.filters button{padding:8px 18px;border-radius:var(--pill);border:1.6px solid var(--line-2);
  background:#fff;color:var(--ink-2);font:700 12px/1 var(--round);cursor:pointer;
  transition:background .16s,color .16s,border-color .16s}
.filters button:hover{color:var(--cyan);border-color:var(--cyan)}
.filters button.on{background:linear-gradient(100deg,var(--hot),var(--pink-2));
  border-color:transparent;color:#fff;box-shadow:0 5px 14px rgba(255,95,158,.3)}
/* 名册：单页角色展示（左右箭头切换） */
.car-wrap{display:grid;grid-template-columns:1fr 1.05fr;gap:16px;align-items:stretch}
.car-photo{position:relative;border-radius:22px;overflow:hidden;
  aspect-ratio:1/1;width:100%;max-width:400px;margin:0 auto;
  background:linear-gradient(140deg,var(--cyan-soft),var(--pink-soft));
  border:3px solid var(--pink-2);box-shadow:0 12px 30px rgba(255,127,178,.22)}
.car-photo img,.car-photo video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block;
  -webkit-user-drag:none;user-select:none;background:#0d1727}
.car-face{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:64px}
.chip-name{position:absolute;left:12px;bottom:12px;z-index:3;background:rgba(255,255,255,.92);
  font:800 13px/1 var(--round);padding:7px 15px;border-radius:var(--pill);
  border:1.6px solid var(--pink-2);color:var(--hot);box-shadow:0 4px 10px rgba(255,127,178,.28)}
.chip-signed{position:absolute;right:12px;top:12px;z-index:3;background:linear-gradient(100deg,var(--hot),var(--pink-2));
  color:#fff;font:800 10px/1 var(--mono);letter-spacing:.12em;padding:5px 11px;border-radius:var(--pill);
  box-shadow:0 4px 10px rgba(255,95,158,.35)}
.car-info{background:linear-gradient(150deg,#fff 60%,var(--pink-soft));border:2px solid var(--line);
  border-radius:22px;padding:20px 22px;box-shadow:var(--soft)}
.ci-name{font-size:22px;font-weight:800;color:var(--ink);display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.ci-type{font:800 10.5px/1 var(--mono);letter-spacing:.12em;color:#fff;
  background:linear-gradient(100deg,var(--cyan),var(--cyan-2));padding:5px 12px;border-radius:var(--pill)}
.ci-row{margin-top:12px;font-size:13px;line-height:1.95;color:#3d6377}
.ci-k{display:inline-block;font:800 10px/1.6 var(--mono);letter-spacing:.16em;color:var(--cyan);margin-right:8px}
.car-nav{display:flex;align-items:center;justify-content:center;gap:16px;margin-top:16px}
.car-count{font:800 11px/1 var(--mono);color:var(--ink-3);letter-spacing:.14em}
.car-arrow{padding:11px 22px;border-radius:var(--pill);border:2px solid var(--cyan-2);background:#fff;
  color:var(--cyan);font:800 13px/1 var(--round);cursor:pointer;
  transition:background .16s,transform .16s,box-shadow .16s}
.car-arrow:hover{background:var(--cyan-soft);transform:translateY(-2px);box-shadow:0 6px 14px rgba(73,184,221,.25)}

.fields{display:grid;grid-template-columns:repeat(2,1fr);gap:20px 24px}
.field label{display:flex;align-items:center;gap:7px;margin-bottom:9px;
  font:700 10.5px/1 var(--mono);letter-spacing:.18em;color:var(--ink-2)}
.field label s{width:6px;height:6px;border-radius:50%;background:var(--pink);text-decoration:none}
.fld{width:100%;background:var(--cyan-soft);border:1.6px solid var(--line-2);
  border-radius:var(--r-sm);padding:12px 14px;font-size:14px;color:var(--ink);transition:border-color .16s,box-shadow .16s}
.fld:focus{outline:0;border-color:var(--pink);box-shadow:0 0 0 4px rgba(255,127,178,.16);background:#fff}
.fld::placeholder{color:var(--ink-3)}
select.fld{cursor:pointer;-webkit-appearance:none;appearance:none;
  background-image:linear-gradient(45deg,transparent 50%,var(--ink-2) 50%),linear-gradient(135deg,var(--ink-2) 50%,transparent 50%);
  background-position:calc(100% - 18px) 50%,calc(100% - 13px) 50%;
  background-size:5px 5px,5px 5px;background-repeat:no-repeat}
select.fld option{background:#fff;color:var(--ink)}
textarea.fld{resize:vertical;min-height:86px;line-height:1.8}
.hint{margin-top:8px;font-size:11.5px;color:var(--ink-3);line-height:1.7}

.preview{border:1.6px solid var(--line);border-radius:var(--r-sm);background:var(--cyan-soft)}
.preview pre{margin:0;padding:16px 18px;font:400 12px/1.9 var(--mono);color:#3d6377;
  white-space:pre-wrap;word-break:break-word;max-height:300px;overflow-y:auto}
.start-row{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:18px}

#modal{display:none;position:fixed;inset:0;z-index:300;background:rgba(40,110,150,.4);
  backdrop-filter:blur(6px);align-items:center;justify-content:center;padding:20px}
#modal.on{display:flex}
.sheet{width:min(540px,100%);max-height:86vh;overflow-y:auto;
  background:var(--card);border:2.5px solid var(--pink-2);border-radius:26px;
  box-shadow:0 20px 60px rgba(255,127,178,.35);overflow:hidden}
.sheet-hd{display:flex;align-items:center;gap:14px;padding:20px;
  background:linear-gradient(100deg,var(--pink-soft),var(--cyan-soft))}
.sheet-face{width:62px;height:62px;flex:0 0 62px;border-radius:50%;
  display:flex;align-items:center;justify-content:center;font-size:30px;
  border:2px solid #fff;box-shadow:0 4px 14px rgba(255,127,178,.3)}
.sheet-tt{font-size:19px;font-weight:800;color:var(--ink)}
.sheet-st{margin-top:4px;font:700 10.5px/1 var(--mono);letter-spacing:.14em;color:var(--ink-3)}
.sheet-x{margin-left:auto;background:#fff;border:1.6px solid var(--line-2);color:var(--ink-2);
  width:30px;height:30px;border-radius:50%;font-size:19px;line-height:1;cursor:pointer;
  transition:background .16s,color .16s}
.sheet-x:hover{background:var(--hot);border-color:var(--hot);color:#fff}
.sheet-bd{padding:8px 20px 20px}
.row{display:flex;gap:14px;padding:12px 0;border-bottom:1px solid var(--line)}
.row:last-child{border-bottom:0}
.row-k{flex:0 0 78px;font:800 10.5px/1.9 var(--mono);letter-spacing:.14em;color:var(--pink)}
.row-v{flex:1;font-size:14px;line-height:1.85;color:#3d6377}

@media(max-width:900px){
  #app{grid-template-columns:1fr;grid-template-rows:auto 1fr}
  .side{border-right:0;border-bottom:2px solid var(--line);padding:12px}
  .brand{padding:2px 4px 10px}
  .nav{flex-direction:row;gap:8px;overflow-x:auto;padding-bottom:4px}
  .nav-cap,.side-box{display:none}
  .nav-item{padding:9px 16px;white-space:nowrap}
  .kpis,.flow{grid-template-columns:repeat(2,1fr)}
  .fields{grid-template-columns:1fr}
  .viewport{padding:16px 16px 104px}
  .nav-buttons{bottom:14px;gap:8px}
  .nav-btn{padding:11px 18px;font-size:12px}
  .collage{grid-template-columns:repeat(2,1fr)}
  .car-wrap{grid-template-columns:1fr}
  .car-photo{max-width:320px}
  .tb-search{display:none}
  .hero-photo{height:260px}
}

/* ══════════ 手机端适配（≤600px）：收窄左右固定尺寸，消除横向溢出（显示不全） ══════════ */
@media(max-width:600px){
  /* ① 关键：让 1fr 栅格列可收缩到视口内（否则内容的最小宽度会把整页撑开） */
  #app{grid-template-columns:minmax(0,1fr)!important}
  /* ② 所有主要容器允许收缩，避免被内容 min-content 顶宽 */
  .side,.main,.viewport,.view,.panel,.topbar,.brand,.nav,.car-wrap,.car-info,.hero-card,.hero-panel,.sheet,.tbl-wrap{min-width:0!important}
  img,video,table{max-width:100%!important}
  /* ③ 收窄左右内边距 */
  .ins-wrap{max-width:100%!important;padding:14px 12px 26px!important}
  .side{padding:10px!important}
  .brand{padding:2px 4px 8px!important}
  .nav{gap:6px!important}
  .nav-item{padding:8px 12px!important;font-size:12.5px!important}
  .topbar{padding:10px 12px!important;gap:8px!important;flex-wrap:wrap!important}
  .topbar h2{font-size:15px!important}
  .viewport{padding:12px 10px 96px!important}
  .panel-hd{padding:11px 13px!important}
  .panel-hd em{display:none!important}
  .panel-bd{padding:13px!important}
  /* ④ 封面 */
  .hero-photo{height:220px!important}
  .hero-panel{padding:14px 14px 18px!important}
  .hero-title{font-size:clamp(28px,8.5vw,36px)!important}
  .hero-actions{gap:9px!important}
  .btn{padding:11px 18px!important;font-size:13px!important}
  /* ⑤ 栅格降列 */
  .kpis,.flow{grid-template-columns:repeat(2,1fr)!important;gap:9px!important}
  .kpi{padding:12px!important}
  .kpi-v{font-size:21px!important}
  .collage{grid-template-columns:repeat(2,1fr)!important;gap:9px!important}
  .fields{gap:16px!important}
  .car-photo{max-width:100%!important}
  .car-info{padding:16px 15px!important}
  .ci-name{font-size:19px!important}
  /* ⑥ 弹窗 / 表格 */
  .sheet-hd{padding:16px!important}
  .sheet-bd{padding:6px 14px 16px!important}
  .row-k{flex:0 0 58px!important}
  .tbl-wrap{overflow-x:auto!important;-webkit-overflow-scrolling:touch}
  .tbl th,.tbl td{padding:9px 10px!important;font-size:12.5px!important}
  .tbl td:first-child{white-space:normal!important}
  /* ⑦ 底部翻页按钮 */
  .nav-buttons{max-width:96vw!important;gap:6px!important;bottom:12px!important}
  .nav-btn{padding:10px 14px!important;font-size:11.5px!important;letter-spacing:0!important}
  /* ⑧ 长文本防溢出 */
  .prose{font-size:13.5px!important}
  .prose,.row-v,.ci-row,.step-d,.kpi-n,.hint{overflow-wrap:anywhere}
}
@media(max-width:380px){
