/* ═══════ 页面顺序（底部三按钮按此翻页） ═══════ */
var ORDER = ['roster','overview','launch'];
var TITLES = {roster:'主播名册',overview:'公司概况',launch:'老板建档 · 本周开局'};
var current = 0;

function show(key){
  var idx = ORDER.indexOf(key);
  if(idx < 0) idx = 0;
  current = idx;
  var vs = document.querySelectorAll('.view');
  for(var i=0;i<vs.length;i++) vs[i].classList.toggle('on', vs[i].dataset.view === key);
  var ns = document.querySelectorAll('.nav-item');
  for(var j=0;j<ns.length;j++) ns[j].classList.toggle('on', ns[j].dataset.go === key);
  document.getElementById('viewTitle').textContent = TITLES[key];
  document.querySelector('.viewport').scrollTop = 0;
  document.getElementById('progressBar').style.width = (idx / (ORDER.length - 1) * 100) + '%';
  document.getElementById('btnPrev').style.visibility = idx === 0 ? 'hidden' : 'visible';
  document.getElementById('btnNext').style.visibility = idx === ORDER.length - 1 ? 'hidden' : 'visible';
  /* 跳转到名册页时才开始播放角色视频 */
  if(key === 'roster') playCar();
}
function nextPage(){ if(current < ORDER.length - 1) show(ORDER[current + 1]); }
function prevPage(){ if(current > 0) show(ORDER[current - 1]); }

