function vidName(n){ return VID_NAME[n] || n; }
var carIdx = 0;
/* 名册角色视频：与主页 PV 同策略——优先有声播放，被浏览器拦截时静音保底（从头播一次） */
function playCar(){
  var v = document.getElementById('carVid');
  if(!v) return;
  v.muted = false;
  if(v.paused){ try { v.currentTime = 0; } catch(e){} }
  var p = v.play();
  if(p && p.catch) p.catch(function(){
    setTimeout(function(){
      v.muted = false;
      var q = v.play();
      if(q && q.catch) q.catch(function(){ v.muted = true; v.play().catch(function(){}); });
    }, 350);
  });
}
function renderCar(){
  var t = TALENTS[carIdx];
  var face = document.getElementById('carFace');
  face.style.background = 'linear-gradient(145deg,'+t.c+')';
  face.textContent = t.e;
  /* 视频：不静音 · 自动播放一次（不循环），失败降级 图床图 -> imagehub */
  var vn = vidName(t.n);
  var vid = document.getElementById('carVid');
  vid.dataset.step = '0';
  vid.onerror = function(){
    if(this.dataset.step === '0'){ this.dataset.step = '1'; this.src = VID_BASE + encodeURIComponent(vn) + '1.mp4'; }
    else { this.style.display = 'none'; }
  };
  vid.style.display = 'block';
  vid.muted = false;
  vid.loop = false;
  vid.poster = IMG_BASE + 'SFW/' + encodeURIComponent(t.n) + '/' + SCENES[carIdx % SCENES.length] + '1.webp';
  vid.src = VID_BASE + encodeURIComponent(vn) + '.mp4';
  document.getElementById('carName').textContent = t.n;
  document.getElementById('carBadge').style.display = t.s==='signed' ? 'block' : 'none';
  document.getElementById('carInfo').innerHTML =
    '<div class="ci-name">'+t.n+'<span class="ci-type">'+t.ty+'</span></div>' +
    '<div class="ci-row"><span class="ci-k">LOOK · 外观</span>'+t.look+'</div>' +
    '<div class="ci-row"><span class="ci-k">CORE · 性格内核</span>'+t.core+'</div>' +
    '<div class="ci-row"><span class="ci-k">QUOTE · 口癖</span>'+t.q+'</div>' +
    '<div class="ci-row"><span class="ci-k">ANCHOR · 情感锚点</span>'+t.an+'</div>' +
    '<div class="ci-row"><span class="ci-k">TAG · 专属</span>'+t.t+'</div>' +
    (t.s==='signed' ? '<div class="ci-row"><span class="ci-k">STATUS · 状态</span>已签约 · 依赖 '+t.dep+'/100</div>' : '');
  document.getElementById('carIdx').textContent = (carIdx+1)+' / '+TALENTS.length;
  /* 主页（封面）阶段不播放；跳转到名册页（第二页）后才自动有声播放 */
  var appEl = document.getElementById('app');
  var rvEl = document.querySelector('[data-view="roster"]');
  if(appEl && appEl.style.display !== 'none' && rvEl && rvEl.classList.contains('on')){
    playCar();
  } else {
    vid.pause();
    try { vid.currentTime = 0; } catch(e){}
  }
}
function carStep(d){ carIdx = (carIdx + d + TALENTS.length) % TALENTS.length; renderCar(); }
function openSheet(i){
