/* ══ 地图模态弹窗 ══ */
#mapModal{
  position:fixed;inset:0;z-index:9998;
  display:none;align-items:center;justify-content:center;
}
#mapModal.show{display:flex;animation:mmFade .3s ease}
@keyframes mmFade{from{opacity:0}to{opacity:1}}
#mapModal .mm-overlay{
  position:absolute;inset:0;
  background:rgba(0,0,0,.88);
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  cursor:pointer
}
#mapModal .mm-box{
  position:relative;
  width:96vw;height:92vh;
  background:var(--bg,#0a0612);
  border:1px solid var(--gold,#c9a961);
  border-radius:10px;
  box-shadow:0 16px 60px rgba(0,0,0,.9),0 0 0 1px rgba(201,169,97,.12);
  overflow:hidden;
  animation:mmUp .35s cubic-bezier(.4,0,.2,1)
}
@keyframes mmUp{from{transform:translateY(30px) scale(.95);opacity:0}to{transform:none;opacity:1}}
#mapModal .mm-header{
  position:absolute;top:0;left:0;right:0;height:48px;z-index:10;
  display:flex;align-items:center;justify-content:space-between;
  padding:0 16px;
  background:linear-gradient(180deg,rgba(10,6,18,.95),rgba(10,6,18,.7));
  border-bottom:1px solid rgba(201,169,97,.3)
}
#mapModal .mm-title{
  font-family:var(--fc,serif);font-size:14px;font-weight:700;
  color:var(--gold-bright,#e8c878);letter-spacing:3px;
  display:flex;align-items:center;gap:8px
}
#mapModal .mm-title i{font-size:18px;color:var(--gold,#c9a961)}
#mapModal .mm-close{
  width:34px;height:34px;border-radius:50%;
  background:rgba(255,255,255,.08);
  border:1px solid rgba(201,169,97,.4);
  color:var(--gold,#c9a961);font-size:20px;line-height:1;
  cursor:pointer;display:flex;align-items:center;justify-content:center;
  transition:all .2s;font-family:serif
}
#mapModal .mm-close:hover{
  background:var(--gold,#c9a961);color:#0a0612;
  transform:rotate(90deg)
}
#mapModal .mm-iframe{
  position:absolute;top:48px;left:0;right:0;bottom:0;
  width:100%;height:calc(100% - 48px);
  border:none
}

/* ════════ 全局性能优化（PC+手机）：关闭所有持续特效，仅保留交互触发动画 ════════ */
/* Canvas 星空隐藏（JS 已跳过启动，这里隐藏元素省合成层） */
#starfield{display:none!important}
/* body 多层径向渐变简化为单层，减少背景合成开销 */
body{background:
  radial-gradient(ellipse 60% 50% at 20% 30%, rgba(157,108,255,0.12) 0%, transparent 60%),
  #08050f!important}
/* 关闭所有持续循环动画（runeRotate/spiritPulse/spiritFloat/ringSpin/blink/broadcast-pulse/cursorBlink） */
#rune-circle,#rune-circle::after,.empty-sigil::after,
.spirit-glow,.spirit-svg,.spirit-art,
.scene-tag .dot,.broadcast-tag i,.dialog-text .cursor{
  animation:none!important;
}
/* 移除所有 filter:blur / drop-shadow（SVG 滤镜与模糊是 GPU 最大负担源） */
.spirit-glow{filter:none!important}
.spirit-svg{filter:none!important}
.spirit-art{filter:none!important}
.brand-sigil svg{filter:none!important}
.ring-fill.hp,.ring-fill.mp,.ring-fill.sp{filter:none!important}
.hex-node.active .hex-glow{filter:none!important}
/* 移除所有 backdrop-filter（改为纯色半透明背景补偿视觉层次） */
*{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}
.cg-fs-overlay{background:rgba(8,5,15,0.99)!important}
.cg-modal-overlay,.nearby-detail-layer,.portal-overlay{background:rgba(8,5,15,0.97)!important}
#mapModal{background:rgba(0,0,0,0.95)!important}
/* 大半径 box-shadow（40-60px）统一降到 16px，减少 GPU 阴影计算 */
.nearby-detail,.item-detail,.skill-crimson,.skill-violet,.media-detail,.world-detail,
.portal-card,.cg-modal,.rune-card-sel,.char-detail{
  box-shadow:0 4px 16px rgba(0,0,0,0.6)!important;
}
/* hex 节点过渡简化 */
.hex-node{transition:transform .2s ease!important}

/* ════════ 手机端性能降级（激进版，防发热卡顿） ════════ */
@media (max-width: 820px){
  /* 关闭 Canvas 星空（JS 已跳过启动，这里隐藏元素省合成层） */
  #starfield{display:none!important}
  /* 简化 body 多层径向渐变为单层，减少背景合成开销 */
  body{background:
    radial-gradient(ellipse 60% 50% at 20% 30%, rgba(157,108,255,0.12) 0%, transparent 60%),
    #08050f!important}
  /* 关闭大元素持续旋转（120vmin GPU 合成开销大） */
  #rune-circle,#rune-circle::after,.empty-sigil::after{animation:none!important}
  /* 关闭灵体浮动（避免 filter 与 transform 同帧重算） */
  .spirit-svg,.spirit-art{animation:none!important}
  /* spiritPulse 进一步减慢，降低重绘频率 */
  .spirit-glow{animation-duration:10s!important}
  /* 装饰性闪烁/脉动动画保留（opacity 单属性，开销极小） */
  /* broadcast 滚动保留，但减慢以降低 transform 合成频率 */
  .broadcast-inner{animation-duration:45s!important}
  /* 所有 backdrop-filter 移除，改为纯色半透明背景（手机 GPU 最大负担源） */
  .dialog-scroll,.portal-overlay,.toast,
  .cg-fs-overlay,.cg-modal-overlay,.nearby-detail-layer,
  input,textarea,select{
    backdrop-filter:none!important;
    -webkit-backdrop-filter:none!important;
  }
  /* 弹窗背景加深，补偿 backdrop-filter 移除后的视觉层次 */
  .cg-fs-overlay{background:rgba(8,5,15,0.99)!important}
  .cg-modal-overlay,.nearby-detail-layer,.portal-overlay{background:rgba(8,5,15,0.97)!important}
  /* 大半径 box-shadow（40-60px）统一降到 16px，减少 GPU 阴影计算 */
  .nearby-detail,.item-detail,.skill-crimson,.skill-violet,.media-detail,.world-detail,
  .portal-card,.cg-modal,.rune-card-sel{
    box-shadow:0 4px 16px rgba(0,0,0,0.6)!important;
  }
  /* hex 节点过渡简化 */
  .hex-node{transition:transform .2s ease!important}
  /* 状态环 drop-shadow 移除，减少 SVG 滤镜开销 */
  .ring-fill.hp,.ring-fill.mp,.ring-fill.sp{filter:none!important}
}

/* ════════ 无障碍：尊重减少动效偏好 ════════ */
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{
    animation-duration:.01ms!important;
    animation-iteration-count:1!important;
    transition-duration:.01ms!important;
  }
  #rune-circle,.spirit-glow,.spirit-svg,.spirit-art,.empty-sigil::after,
  .broadcast-inner,.ring-fill{animation:none!important;transition:none!important}
}
