/* ════════ 杂志PV主题 · FOOT HEAVEN IDOL GRAVURE ════════ */
:root{
  --pv-ink:#05060E; --pv-night:#0B1030; --pv-blue:#12306B; --pv-violet:#3A1E6E;
  --pv-mag:#E0479B; --pv-cyan:#7FE3FF; --pv-star:#FFE27A; --pv-paper:#EDE7D8;
  --pv-line:rgba(255,255,255,0.16);
}
html,body{background:var(--pv-ink)}
#app{
  border:12px solid var(--pv-paper);
  border-radius:3px;
  background:
    radial-gradient(rgba(255,255,255,0.05) 1px, transparent 1.4px) 0 0/7px 7px,
    radial-gradient(120% 80% at 80% 16%, rgba(224,71,155,0.18) 0%, transparent 56%),
    radial-gradient(120% 90% at 10% 90%, rgba(127,227,255,0.13) 0%, transparent 55%),
    linear-gradient(160deg, #0B1030 0%, #090A20 46%, #140832 100%);
  box-shadow:0 0 0 1px rgba(0,0,0,.65), 0 20px 60px rgba(0,0,0,.75), inset 0 0 90px rgba(0,0,0,.55);
  overflow:hidden;
}
/* ── masthead ── */
.top-bar{background:linear-gradient(180deg,rgba(5,6,14,.92),transparent);border-bottom:1px solid var(--pv-line)}
.brand-title{font-size:19px;letter-spacing:5px;color:#fff;text-shadow:0 0 14px rgba(127,227,255,.75),0 0 26px rgba(224,71,155,.5)}
.brand-sub{color:var(--pv-star);letter-spacing:3px}
.pv-title{display:flex;flex-direction:column;line-height:1;padding:0 4px 0 16px;border-left:1px solid var(--pv-line)}
.pv-title-main{font-family:var(--fc);font-weight:900;font-size:24px;letter-spacing:4px;color:#fff;text-shadow:0 2px 18px rgba(127,227,255,.6),0 0 30px rgba(224,71,155,.45)}
.pv-title-sub{font-family:var(--fi);font-style:italic;font-size:10px;letter-spacing:4px;color:var(--pv-cyan);margin-top:3px}
.pv-chips .res-chip{border:1px solid var(--pv-line);background:rgba(255,255,255,.045);border-radius:999px;padding:4px 10px;transition:.2s}
.pv-chips .res-chip:hover{border-color:var(--pv-star);background:rgba(255,226,122,.1);box-shadow:0 0 14px rgba(255,226,122,.3)}
.pv-chips .res-val{font-family:var(--fc);font-size:11px;letter-spacing:1px;color:#EAF2FF}
/* ── 主视觉层 ── */
.compass-stage{position:relative;overflow:hidden;align-items:flex-start;justify-content:center;padding-left:4px}
.pv-hero{position:absolute;inset:0;z-index:1;pointer-events:none}
.pv-hero-burst{position:absolute;top:-14%;right:-8%;width:74%;height:130%;
  background:radial-gradient(circle at 68% 42%, rgba(127,227,255,.32) 0%, rgba(224,71,155,.18) 34%, transparent 70%);filter:blur(8px)}
.pv-hero-img{position:absolute;top:0;right:0;height:100%;width:auto;max-width:none;object-fit:contain;object-position:right top;
  opacity:.55;filter:drop-shadow(0 0 30px rgba(127,227,255,.4)) saturate(1.05);
  -webkit-mask-image:linear-gradient(100deg,transparent 0%,#000 36%,#000 100%);
  mask-image:linear-gradient(100deg,transparent 0%,#000 36%,#000 100%)}
.pv-code{position:absolute;left:14px;top:12px;z-index:4;font-family:var(--fi);font-size:9px;letter-spacing:2px;color:rgba(255,255,255,.55);pointer-events:none}
.pv-collage{position:absolute;top:14px;right:14px;z-index:4;display:flex;flex-direction:column;gap:8px;pointer-events:none}
.pv-cell{width:86px;background:#0A0A1E;border:1px solid var(--pv-line);box-shadow:0 8px 20px rgba(0,0,0,.55);transform:rotate(-2deg)}
.pv-cell:nth-child(2){transform:rotate(2deg)}
.pv-cell:nth-child(3){transform:rotate(-1deg)}
.pv-cell img{display:block;width:100%;height:62px;object-fit:cover;object-position:top center}
.pv-cell span{display:block;font-family:var(--fc);font-size:8px;letter-spacing:1.5px;color:var(--pv-cyan);padding:3px 5px;border-top:1px solid var(--pv-line)}
.pv-vertical{position:absolute;right:16px;bottom:46px;z-index:4;writing-mode:vertical-rl;font-family:var(--fi);font-size:12px;letter-spacing:5px;color:rgba(255,255,255,.8);text-shadow:0 0 12px rgba(127,227,255,.55);pointer-events:none}
.pv-eq{position:absolute;left:14px;bottom:12px;z-index:4;display:flex;align-items:flex-end;gap:3px;height:22px;pointer-events:none}
.pv-eq i{width:3px;background:linear-gradient(180deg,var(--pv-cyan),var(--pv-mag));border-radius:1px;transform-origin:bottom;animation:pvEq 1.1s ease-in-out infinite}
.pv-eq i:nth-child(1){height:40%;animation-delay:0s}
.pv-eq i:nth-child(2){height:75%;animation-delay:.15s}
.pv-eq i:nth-child(3){height:55%;animation-delay:.3s}
.pv-eq i:nth-child(4){height:95%;animation-delay:.45s}
.pv-eq i:nth-child(5){height:60%;animation-delay:.6s}
.pv-eq i:nth-child(6){height:85%;animation-delay:.75s}
.pv-eq i:nth-child(7){height:45%;animation-delay:.9s}
@keyframes pvEq{0%,100%{transform:scaleY(.35)}50%{transform:scaleY(1)}}
.pv-spark{position:absolute;z-index:5;color:var(--pv-star);font-size:14px;text-shadow:0 0 12px var(--pv-star);animation:pvTwk 3s ease-in-out infinite;pointer-events:none}
.pv-spark.s1{top:12%;left:36%}
.pv-spark.s2{top:30%;right:28%;animation-delay:1s}
.pv-spark.s3{bottom:24%;left:22%;animation-delay:1.8s}
.pv-spark.s4{top:56%;left:58%;animation-delay:.6s}
@keyframes pvTwk{0%,100%{opacity:.2;transform:scale(.8) rotate(0)}50%{opacity:1;transform:scale(1.18) rotate(20deg)}}
/* ── 数据卡片（datafile） ── */
.home-panel{position:relative;z-index:3;width:100%;max-width:336px;margin:0;align-self:center;padding:0 12px 0 6px}
.home-card{background:linear-gradient(135deg,rgba(18,48,107,.5),rgba(58,30,110,.34));border:1px solid var(--pv-line);border-left:2px solid var(--pv-star);border-radius:2px;padding:10px 12px;backdrop-filter:blur(3px);box-shadow:0 10px 26px rgba(0,0,0,.45)}
.home-title{font-size:11px;letter-spacing:3px;color:var(--pv-star)}
.home-title i{color:var(--pv-star)}
.home-world-line{font-size:15px;letter-spacing:1px}
.home-world-sub{color:rgba(255,255,255,.55)}
.home-world-sub span{color:var(--pv-cyan)}
.sense-row{font-size:11.5px}
.sense-row i{color:var(--pv-cyan)}
.sense-label{color:rgba(255,255,255,.5);letter-spacing:1px}
.home-net .net-item{font-size:11.5px}
/* ── 底部对话区 / 剧情选项 ── */
.dialog-zone{background:linear-gradient(0deg,rgba(5,6,14,.97),rgba(5,6,14,.55));border-top:1px solid var(--pv-line)}
.dialog-text{color:#EAF2FF}
.speaker-name{font-family:var(--fc);letter-spacing:2px;color:#fff;text-shadow:0 0 12px rgba(127,227,255,.5)}
.speaker-role{color:var(--pv-star)}
.choice-btn{border:1px solid var(--pv-line);background:rgba(255,255,255,.04);border-radius:2px;transition:.2s}
.choice-btn:hover{border-color:var(--pv-star);background:rgba(255,226,122,.08);box-shadow:0 0 16px rgba(255,226,122,.28);transform:translateX(3px)}
.choice-rune{color:var(--pv-star);text-shadow:0 0 10px rgba(255,226,122,.6)}
.input-field{background:rgba(255,255,255,.05);border:1px solid var(--pv-line);color:#fff}
.cast-btn{background:linear-gradient(135deg,var(--pv-mag),var(--pv-blue));color:#fff;box-shadow:0 0 16px rgba(224,71,155,.35)}
/* ════════ 杂志PV · 弹窗 / 星门CG / 地图 / 对话区（高性能版） ════════
   原则：全部用静态渐变+边框+网点；transition 仅 transform/opacity；
   不使用 filter/backdrop-filter，不新增持续大范围动画。 */
.pv-hero-burst{filter:none!important;background:radial-gradient(circle at 70% 42%, rgba(127,227,255,.26) 0%, rgba(224,71,155,.14) 38%, transparent 72%)!important}
.pv-hero-img{filter:none!important}

/* —— 底部对话区 / 剧情选项 —— */
.dialog-zone{border-top:1px solid var(--pv-line);background:linear-gradient(0deg,#05060E 0%, rgba(5,6,14,.88) 62%, rgba(5,6,14,.42) 100%)}
.dialog-scroll{position:relative;border:1px solid var(--pv-line);border-radius:2px;padding:14px 16px 12px;background:linear-gradient(135deg, rgba(18,48,107,.34), rgba(20,8,50,.46))}
.dialog-scroll::after{content:'FOOT HEAVEN · DAILY';position:absolute;top:6px;right:10px;font-family:var(--fc);font-size:8px;letter-spacing:3px;color:rgba(255,226,122,.5)}
.speaker-glyph{width:44px;height:44px;border:2px solid var(--pv-star);border-radius:2px;box-shadow:0 0 0 3px rgba(255,226,122,.12);overflow:hidden}
.speaker-name{font-family:var(--fc);font-size:15px;letter-spacing:2px}
.dialog-text{position:relative;padding-left:16px;font-size:13px;line-height:1.7;border-left:2px solid var(--pv-star)}
.dialog-text::before{content:'\201C';position:absolute;left:2px;top:-10px;font-family:var(--fc);font-size:26px;line-height:1;color:rgba(255,226,122,.45)}
.choices{gap:6px}
.choice-btn{border:1px solid var(--pv-line);border-left:3px solid var(--pv-star);border-radius:1px;padding:8px 12px;background:linear-gradient(90deg, rgba(255,226,122,.06), rgba(255,255,255,.02));transition:transform .18s ease, border-color .18s ease}
.choice-btn::before{transform:scaleX(0);transform-origin:left;transition:transform .22s ease!important;background:linear-gradient(90deg, rgba(127,227,255,.18), transparent)!important}
.choice-btn:hover{transform:translateX(4px);border-left-color:var(--pv-cyan);box-shadow:none!important}
.choice-btn:hover::before{transform:scaleX(1)}
.choice-rune{font-family:var(--fc);font-weight:900;color:var(--pv-star);text-shadow:none}
.choice-meta{font-family:var(--fc);font-size:9px;letter-spacing:1px;color:rgba(255,255,255,.45)}
.input-zone{border:1px solid var(--pv-line);border-radius:2px;background:rgba(255,255,255,.04)}
.input-field{background:transparent!important;border:none!important;color:#fff}
.cast-btn{border-radius:2px;background:linear-gradient(135deg,var(--pv-mag),var(--pv-blue))!important;box-shadow:none!important;transition:transform .15s ease, opacity .15s ease}
.cast-btn:hover{transform:translateX(2px);opacity:.92}

/* —— 点击弹窗（主播详情 / 状态详情 / 道具·技能·媒体·世界详情） —— */
.nearby-detail-layer{padding:20px 12px}
.nearby-detail{width:min(432px,94vw);max-height:86vh;overflow-y:auto;overscroll-behavior:contain;
  border:1px solid var(--pv-line);border-top:3px solid var(--pv-star);border-radius:2px;padding:0 0 16px;
  background-image:radial-gradient(rgba(255,255,255,.045) 1px, transparent 1.3px), linear-gradient(165deg,#0C1330 0%, #0A0A22 52%, #160B33 100%);
  background-size:8px 8px, auto;
  box-shadow:0 16px 44px rgba(0,0,0,.72)!important}
.detail-banner{position:relative;height:134px;overflow:hidden;border-bottom:1px solid var(--pv-line);
  background:linear-gradient(120deg, rgba(224,71,155,.34), rgba(18,48,107,.55))}
.detail-banner img{display:block;width:100%;height:100%;object-fit:cover;object-position:top center}
.detail-banner::after{content:'';position:absolute;inset:0;background:linear-gradient(180deg, transparent 32%, rgba(5,6,14,.86) 100%)}
.detail-banner-tag{position:absolute;left:12px;bottom:8px;z-index:2;font-family:var(--fc);font-size:11px;letter-spacing:2px;color:#fff;text-shadow:0 1px 8px #000}
.detail-avatar{position:relative;z-index:3;width:64px;height:64px;border-radius:2px;border:2px solid var(--pv-star);box-shadow:0 0 0 3px rgba(255,226,122,.14);margin:-34px 0 0 14px;background-size:cover;background-position:center}
.detail-header{padding:8px 14px 2px}
.detail-name{font-family:var(--fc);font-size:20px;letter-spacing:2px;color:#fff;text-shadow:0 0 14px rgba(127,227,255,.5)}
.detail-close{width:26px;height:26px;border:1px solid var(--pv-line);border-radius:2px;background:rgba(255,255,255,.06);color:#fff;transition:transform .15s ease, border-color .15s ease, color .15s ease}
.detail-close:hover{transform:scale(1.06);border-color:var(--pv-star);color:var(--pv-star)}
.detail-section{padding:0 14px;margin-bottom:12px}
.detail-section-title{display:flex;align-items:center;gap:6px;font-family:var(--fc);font-size:11px;letter-spacing:3px;color:var(--pv-star);border-bottom:1px solid var(--pv-line);padding-bottom:5px;margin-bottom:6px}
.detail-row{display:flex;align-items:center;gap:8px;padding:4px 0;border-bottom:1px dashed rgba(255,255,255,.08)}
.detail-row:hover{background:rgba(255,255,255,.035)}
.detail-row i{color:var(--pv-cyan)}
.detail-label{flex:1;font-size:11px;letter-spacing:.5px;color:rgba(255,255,255,.55)}
.detail-val{max-width:62%;font-size:12px;color:#fff;text-align:right}
.detail-block{margin:0 14px 12px;padding:10px 12px;border:1px solid var(--pv-line);border-left:3px solid var(--pv-mag);border-radius:1px;background:linear-gradient(135deg, rgba(224,71,155,.10), rgba(255,255,255,.02))}
.detail-block-title{font-family:var(--fc);font-size:10px;letter-spacing:2px;color:var(--pv-mag)}
.detail-thought{margin-top:5px;font-size:12.5px;line-height:1.7;color:#EAF2FF}
.detail-thumbs{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;padding:0 14px;margin-bottom:12px}
.detail-thumb{position:relative;aspect-ratio:1/1;border:1px solid var(--pv-line);border-radius:1px;overflow:hidden;background:linear-gradient(135deg, rgba(127,227,255,.14), rgba(224,71,155,.12))}
.detail-thumb img{display:block;width:100%;height:100%;object-fit:cover;object-position:top center}

/* —— 星门（CG画廊容器） —— */
.portal-frame{position:relative;border:2px solid var(--pv-line);border-top:3px solid var(--pv-star);border-radius:3px;overflow:hidden;background:linear-gradient(170deg,#0C1330,#090A20 55%,#150A31)}
.portal-header{position:relative;min-height:98px;padding:18px 18px 14px;border-bottom:1px solid var(--pv-line);
  background-image:radial-gradient(rgba(255,255,255,.05) 1px, transparent 1.3px), linear-gradient(100deg, rgba(224,71,155,.34), rgba(18,48,107,.5) 62%, rgba(5,6,14,.25));
  background-size:8px 8px, auto}
.portal-header::before{content:'';position:absolute;inset:0;pointer-events:none;opacity:.26;
  background:url('https://zyxjack123.top/足控天堂/立绘/星街彗星.webp') center 18%/cover no-repeat}
.portal-header::after{content:'CG GALLERY';position:absolute;right:14px;bottom:8px;font-family:var(--fc);font-size:24px;letter-spacing:6px;color:rgba(255,255,255,.08);pointer-events:none}
.portal-title h2{font-family:var(--fc);font-size:22px;letter-spacing:3px;color:#fff;text-shadow:0 0 16px rgba(127,227,255,.5)}
.portal-title .en{font-family:var(--fi);letter-spacing:4px;color:var(--pv-star)}
.portal-sigil{border:1px solid var(--pv-line);border-radius:2px;color:var(--pv-star)}
.portal-close{transition:transform .15s ease, color .15s ease}
.portal-close:hover{transform:scale(1.06);color:var(--pv-star)}
.portal-tabs{padding:10px 14px 0;gap:6px;border-bottom:1px solid var(--pv-line)}
.portal-tab{font-family:var(--fc);letter-spacing:2px;border:1px solid var(--pv-line);border-bottom:none;border-radius:2px 2px 0 0;padding:6px 14px;color:rgba(255,255,255,.6);background:rgba(255,255,255,.03);transition:color .15s ease, background-color .15s ease}
.portal-tab.active{color:#0A0A1E;background:linear-gradient(135deg,var(--pv-star),#FFB84D);border-color:var(--pv-star)}
.portal-body{padding:14px}

/* —— CG 画廊 —— */
.cg-domain-bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.cg-domain-btn{font-family:var(--fc);font-size:11px;letter-spacing:1px;border:1px solid var(--pv-line);border-radius:999px;padding:4px 12px;color:rgba(255,255,255,.7);background:rgba(255,255,255,.04);transition:transform .15s ease, border-color .15s ease, color .15s ease}
.cg-domain-btn:hover{transform:translateY(-1px)}
.cg-domain-btn.active{color:#0A0A1E;background:linear-gradient(135deg,var(--pv-cyan),#4DD4E8);border-color:var(--pv-cyan)}
.cg-domain-cnt{margin-left:5px;font-size:9px;opacity:.7}
.cg-stats-row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:8px}
.cg-stat-chip{border:1px solid var(--pv-line);border-left:2px solid var(--pv-star);border-radius:1px;padding:8px 10px;background:linear-gradient(135deg, rgba(18,48,107,.45), rgba(255,255,255,.02))}
.cg-stat-label{font-family:var(--fc);font-size:9px;letter-spacing:2px;color:rgba(255,255,255,.5)}
.cg-stat-val{font-family:var(--fc);font-size:18px;color:#fff}
.cg-progress-bar{height:4px;margin-bottom:10px;border-radius:2px;overflow:hidden;background:rgba(255,255,255,.08)}
.cg-progress-fill{height:100%;background:linear-gradient(90deg,var(--pv-cyan),var(--pv-mag))}
.cg-cat-toggle{display:flex;gap:6px;margin-bottom:8px}
.cg-cat-btn{font-family:var(--fc);font-size:11px;letter-spacing:2px;border:1px solid var(--pv-line);border-radius:2px;padding:6px 16px;color:rgba(255,255,255,.65);background:rgba(255,255,255,.03);transition:color .15s ease, background-color .15s ease}
.cg-cat-btn.active{color:#0A0A1E;background:linear-gradient(135deg,var(--pv-mag),#B03A7A);border-color:var(--pv-mag)}
.cg-cache-bar{display:flex;align-items:center;gap:8px;margin-bottom:10px}
.cg-cache-btn{font-family:var(--fc);font-size:10px;letter-spacing:1px;border:1px solid var(--pv-line);border-radius:2px;padding:4px 10px;color:rgba(255,255,255,.7);background:rgba(255,255,255,.04)}
.cg-cache-status{font-size:10px;color:rgba(255,255,255,.45)}
.cg-char-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:10px}
.cg-char-card{position:relative;border:1px solid var(--pv-line);border-radius:1px;overflow:hidden;background:#0A0A1E;transition:transform .18s ease, border-color .18s ease}
.cg-char-card:hover{transform:translateY(-3px);border-color:var(--pv-star)}
.cg-char-thumb{height:112px;background-size:cover;background-position:top center}
.cg-char-thumb-fallback{height:112px;display:flex;align-items:center;justify-content:center;font-size:30px;color:rgba(255,255,255,.25);background:linear-gradient(135deg, rgba(18,48,107,.5), rgba(224,71,155,.18))}
.cg-char-overlay{position:absolute;left:0;right:0;bottom:0;padding:6px 7px;background:linear-gradient(0deg, rgba(5,6,14,.95), rgba(5,6,14,.55) 60%, transparent)}
.cg-char-name{font-family:var(--fc);font-size:11px;letter-spacing:1px;color:#fff}
.cg-char-count{font-size:9px;color:var(--pv-cyan)}
.cg-char-prog{height:2px;margin-top:4px;background:rgba(255,255,255,.12)}
.cg-char-prog-fill{height:100%;background:var(--pv-star)}
.cg-scene-cell{border:1px solid var(--pv-line);border-radius:1px;overflow:hidden;transition:transform .18s ease, border-color .18s ease}
.cg-scene-cell:hover{transform:translateY(-2px);border-color:var(--pv-star)}
.cg-modal{border:2px solid var(--pv-line);border-top:3px solid var(--pv-star);border-radius:2px;background:linear-gradient(165deg,#0C1330,#0A0A22 55%,#160B33);box-shadow:0 16px 44px rgba(0,0,0,.72)!important}
.cg-modal-section-title{font-family:var(--fc);letter-spacing:2px}
.cg-fs-overlay{background:rgba(3,4,10,.985)!important}
.cg-fs-top{border-bottom:1px solid var(--pv-line);background:linear-gradient(180deg, rgba(5,6,14,.92), transparent)}
.cg-fs-title{font-family:var(--fc);letter-spacing:2px}
.cg-fs-arrow{border:1px solid var(--pv-line);background:rgba(255,255,255,.06)}
.cg-fs-arrow:hover{background:rgba(255,226,122,.22)}
.cg-fs-dot{background:rgba(255,255,255,.25)}
.cg-fs-dot.cur{background:var(--pv-star)}
.portal-empty h3{font-family:var(--fc);letter-spacing:2px}

/* —— 地图 —— */
#mapModal .mm-box{position:relative;border:2px solid var(--pv-line);border-top:3px solid var(--pv-star);border-radius:2px;overflow:hidden;background:linear-gradient(165deg,#0C1330,#0A0A22 55%,#150A31);box-shadow:0 16px 44px rgba(0,0,0,.75)!important}
#mapModal .mm-header{position:relative;border-bottom:1px solid var(--pv-line);background:linear-gradient(100deg, rgba(127,227,255,.22), rgba(224,71,155,.18))}
#mapModal .mm-header::after{content:'';position:absolute;inset:0;pointer-events:none;opacity:.2;background:url('https://zyxjack123.top/足控天堂/插图/SFW/白上吹雪/微笑1.webp') center 28%/cover no-repeat}
#mapModal .mm-title{font-family:var(--fc);letter-spacing:3px;color:#fff}
#mapModal .mm-title i{color:var(--pv-star)}
#mapModal .mm-close{transition:transform .15s ease, color .15s ease}
#mapModal .mm-close:hover{transform:scale(1.1);color:var(--pv-star)}
#mapModal .mm-iframe{border:none}

/* —— 因特网轮播 —— */
.home-net .net-item{padding-left:14px;border-left:2px solid var(--pv-cyan)}
.home-net .net-item::before{content:'\25B8';position:absolute;left:2px;color:var(--pv-cyan)}

/* —— 动效守卫 —— */
@media (prefers-reduced-motion: reduce){
  .pv-eq i,.pv-spark,.dialog-text .cursor{animation:none!important}
}
/* ════════ 杂志PV v2 · 弹窗内页（封面/分栏/图版/引文/条码） ════════
   性能：全静态渐变与网格线；无 filter/backdrop-filter；仅 transform 过渡；图片懒加载。 */
.nearby-detail.mg{width:min(470px,95vw);max-height:88vh;padding:0;border:1px solid var(--pv-line);border-top:none;border-radius:0;
  background-color:#070A18;
  background-image:
    linear-gradient(180deg, rgba(5,7,18,.34) 0%, rgba(5,7,18,.74) 20%, rgba(5,7,18,.93) 42%, rgba(5,7,18,.965) 72%, rgba(5,7,18,.97) 100%),
    var(--mg-poster, none),
    linear-gradient(115deg,#12234F,#3A1E6E 55%,#6B1747);
  background-size:cover,cover,cover;
  background-position:center top,center top,center;
  background-repeat:no-repeat,no-repeat,no-repeat;
  box-shadow:0 18px 52px rgba(0,0,0,.82)!important}

/* 封面 */
.mg-cover{position:relative;height:214px;overflow:hidden;background:linear-gradient(180deg, rgba(5,7,18,.10) 0%, rgba(5,7,18,.26) 54%, rgba(7,10,24,.97) 100%)}
.mg-cover-grad{position:absolute;inset:0;z-index:2;background:linear-gradient(180deg, rgba(5,7,18,.46) 0%, rgba(5,7,18,.08) 32%, rgba(7,10,24,.98) 100%)}
.mg-mast{position:absolute;top:12px;left:12px;z-index:4;font-family:var(--fc);font-size:12.5px;line-height:1.06;letter-spacing:3px;color:#fff;
  border-left:2px solid var(--pv-star);padding-left:7px;text-shadow:0 1px 10px #000}
.mg-crop{position:absolute;z-index:5;width:13px;height:13px;border:1.5px solid var(--pv-star)}
.mg-crop.tl{top:8px;left:8px;border-right:none;border-bottom:none}
.mg-crop.tr{top:8px;right:8px;border-left:none;border-bottom:none}
.mg-badge{position:absolute;left:14px;top:52px;z-index:4;width:34px;height:34px;display:flex;align-items:center;justify-content:center;font-size:17px;
  border:1px solid var(--pv-line);background:rgba(7,10,24,.62);color:var(--pv-star)}
.mg-close{position:absolute;top:10px;right:10px;z-index:6;width:28px;height:28px;display:flex;align-items:center;justify-content:center;
  border:1px solid rgba(255,255,255,.34);background:rgba(4,6,14,.55);color:#fff;cursor:pointer;font-size:15px;
  transition:transform .15s ease,border-color .15s ease,color .15s ease}
.mg-close:hover{transform:scale(1.06);border-color:var(--pv-star);color:var(--pv-star)}
.mg-cover-txt{position:absolute;left:14px;right:74px;bottom:12px;z-index:4}
.mg-issue{font-family:var(--fc);font-size:8.5px;letter-spacing:2.5px;color:var(--pv-star)}
.mg-name{margin:2px 0 3px;font-family:var(--fc);font-size:30px;line-height:1.04;font-weight:900;letter-spacing:2px;color:#fff;text-shadow:0 2px 18px rgba(0,0,0,.9)}
.mg-subline{font-size:10.5px;letter-spacing:1.4px;color:rgba(255,255,255,.74)}
.mg-barcode{position:absolute;right:12px;bottom:12px;z-index:4;width:52px;height:20px;opacity:.9;
  background:repeating-linear-gradient(90deg,#fff 0 2px,transparent 2px 4px,#fff 4px 5px,transparent 5px 8px,#fff 8px 11px,transparent 11px 13px)}

/* 四格数值条 */
.mg-stats{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--pv-line)}
.mg-stat{padding:9px 8px;border-right:1px solid var(--pv-line)}
.mg-stat:last-child{border-right:none}
.mg-stat-k{font-family:var(--fc);font-size:8.5px;letter-spacing:1.5px;color:rgba(255,255,255,.5)}
.mg-stat-v{font-family:var(--fc);font-size:17px;line-height:1.25;color:#fff}
.mg-stat-bar{height:3px;margin-top:3px;background:rgba(255,255,255,.12)}
.mg-stat-bar i{display:block;height:100%}

/* 导语 */
.mg-lead{margin:12px 14px 0;padding:9px 11px;font-size:11.5px;line-height:1.72;color:#DCE6FF;
  border-left:3px solid var(--pv-mag);background:linear-gradient(90deg,rgba(224,71,155,.15),transparent)}

/* 分节与分栏 */
.mg-sec{padding:0 14px;margin-top:12px}
.mg-sec-h{display:flex;align-items:baseline;gap:8px;font-family:var(--fc);font-size:11.5px;letter-spacing:2.5px;color:var(--pv-star);
  border-bottom:1px solid var(--pv-line);padding-bottom:5px;margin-bottom:7px}
.mg-sec-h span{font-size:8px;letter-spacing:3px;color:rgba(255,255,255,.34)}
.mg-cols{column-count:2;column-gap:16px;column-rule:1px solid rgba(255,255,255,.07)}
.mg-cols .detail-row{break-inside:avoid}
.mg .detail-row{display:flex;align-items:baseline;gap:6px;padding:3px 0;margin:0;background:none;border:none;border-radius:0;
  border-bottom:1px dotted rgba(255,255,255,.15)}
.mg .detail-row i{display:none}
.mg .detail-label{flex:0 0 auto;min-width:0;font-family:var(--fc);font-size:9.5px;color:rgba(255,255,255,.52)}
.mg .detail-val{flex:1;font-size:10.5px;color:#fff;text-align:right;word-break:break-all}
.mg .detail-section-title{color:var(--pv-star)}

/* 图版 */

/* 引文 */
.mg-quote{position:relative;margin:14px 14px 0;padding:12px 10px 10px 30px;border-top:1px solid var(--pv-line);border-bottom:1px solid var(--pv-line)}
.mg-quote::before{content:'\201C';position:absolute;left:3px;top:2px;font-family:var(--fc);font-size:40px;line-height:1;color:rgba(255,226,122,.5)}
.mg-quote .detail-block{margin:0;padding:0;border:none;background:none;border-radius:0}
.mg-quote .detail-block-title{display:none}
.mg-quote .detail-thought{margin:0;padding:0;background:none;border:none;border-radius:0;font-size:12px;font-style:italic;line-height:1.76;color:#EAF2FF}
.mg-quote .detail-thought.empty{font-style:normal;color:rgba(255,255,255,.42)}

/* 页脚 */
.mg-footer{display:flex;justify-content:space-between;gap:10px;margin-top:14px;padding:8px 14px;border-top:1px solid var(--pv-line);
  font-family:var(--fc);font-size:8.5px;letter-spacing:2px;color:rgba(255,255,255,.42);background:rgba(255,255,255,.02)}
/* ════════ 可爱化改造 v3：可读字体（圆润·大字号·低字距）+ 可爱元素 ════════
   参考：浅青/白圆角卡片风。全静态渐变，无 filter，过渡仅 transform/color/border。 */
:root{
  --mg-aqua:#3FA9DC; --mg-aqua-soft:#8FD8F7; --mg-aqua-pale:#EAF7FF;
  --mg-pink:#FF7FB6; --mg-pink-soft:#FFE3EF; --mg-sun:#FFC94D;
  --mg-ink:#12324B; --mg-ink-soft:#5B87A6; --mg-line:#CFE7F6;
  --fc-cute:'Zen Maru Gothic','Noto Sans SC',system-ui,sans-serif;
  --fc-num:'Baloo 2','Zen Maru Gothic','Noto Sans SC',system-ui,sans-serif;
}

/* ───── 弹窗：圆润浅色卡片（海报只在顶部封面带透出） ───── */
.nearby-detail.mg{
  border:3px solid #FFFFFF; border-radius:20px; padding:0 0 14px;
  background-color:#EAF6FF;
  background-image:
    linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,.62) 15%, rgba(244,251,255,.94) 24%, rgba(236,247,255,.97) 100%),
    var(--mg-poster, none),
    linear-gradient(180deg,#FFFFFF,#D9EEFB);
  background-size:auto,cover,auto;
  background-position:center top,center top,center;
  background-repeat:no-repeat,no-repeat,no-repeat;
  box-shadow:0 16px 44px rgba(18,60,92,.42), 0 0 0 7px rgba(143,216,247,.18)!important;
}
.mg-cover{height:206px;background:linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,.42) 58%, #F2FAFF 100%)}
.mg-cover-grad{display:none}
.mg-mast{color:#3FA9DC;border-left:4px solid #8FD8F7;text-shadow:0 1px 0 #fff;font-family:var(--fc-cute);letter-spacing:2px}
.mg-crop{display:none}
.mg-issue{color:#3FA9DC;font-family:var(--fc-num);font-size:11px;letter-spacing:1.5px;font-weight:700}
.mg-name{font-family:var(--fc-cute);font-size:27px;font-weight:900;letter-spacing:0;color:#0E3A57;text-shadow:0 2px 0 rgba(255,255,255,.95),0 6px 16px rgba(255,255,255,.8)}
.mg-subline{font-family:var(--fc-cute);font-size:11.5px;font-weight:700;color:#4E86A8;letter-spacing:.3px}
.mg-barcode{opacity:.55;background:repeating-linear-gradient(90deg,#7FBEDA 0 2px,transparent 2px 4px,#7FBEDA 4px 5px,transparent 5px 8px,#7FBEDA 8px 11px,transparent 11px 13px)}
.mg-badge{border-radius:14px;border:2.5px solid #fff;background:linear-gradient(135deg,#8FD8F7,#3FA9DC);color:#fff!important;box-shadow:0 4px 12px rgba(63,169,220,.4)}
.mg-close{width:30px;height:30px;border-radius:50%;border:2.5px solid #fff;background:#FF9EC8;color:#fff;box-shadow:0 3px 10px rgba(255,127,182,.5);font-size:15px}
.mg-close:hover{transform:scale(1.14) rotate(10deg);border-color:#fff;color:#fff}

/* ───── 四格数值：白色小圆卡 ───── */
.mg-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;padding:10px 12px 4px;border-bottom:none}
.mg-stat{border:none;border-radius:14px;background:#fff;padding:7px 6px 8px;text-align:center;box-shadow:0 2px 0 #DCEEF9, 0 6px 14px rgba(63,169,220,.10)}
.mg-stat-k{font-family:var(--fc-cute);font-size:10.5px;font-weight:700;letter-spacing:0;color:#7FA9C4}
.mg-stat-v{font-family:var(--fc-num);font-size:21px;font-weight:800;color:#0E3A57;line-height:1.12}
.mg-stat-bar{height:6px;border-radius:999px;background:#E9F5FC;margin-top:5px;overflow:hidden}
.mg-stat-bar i{display:block;height:100%;border-radius:999px}

/* ───── 导语：粉调圆角块 ───── */
.mg-lead{margin:10px 12px 0;padding:10px 13px;border-radius:14px;border:none;border-left:5px solid var(--mg-pink);
  background:linear-gradient(90deg,#FFF1F8,#fff);font-size:12px;line-height:1.75;color:#2C5470;font-weight:500}

/* ───── 分节标题：✧ + 中文大字 + 圆角英文标签 ───── */
.mg-sec{padding:0 12px;margin-top:13px}
.mg-sec-h{display:flex;align-items:center;gap:6px;font-family:var(--fc-cute);font-size:14px;font-weight:900;letter-spacing:0;
  color:#0E3A57;border-bottom:none;padding-bottom:7px;margin-bottom:8px;position:relative}
.mg-sec-h::before{content:'\2727';color:#8FD8F7;font-size:15px;line-height:1}
.mg-sec-h::after{content:'';position:absolute;left:0;right:0;bottom:2px;height:2px;border-radius:2px;
  background:repeating-linear-gradient(90deg,#C6E7F9 0 9px,transparent 9px 15px)}
.mg-sec-h span{order:2;margin-left:auto;font-family:var(--fc-num);font-size:9.5px;font-weight:700;letter-spacing:1px;
  color:#66A6C9;background:#EAF6FF;border-radius:999px;padding:2px 8px}

/* ───── 数据行：大字号、低字距、蓝白点线 ───── */
.mg .detail-row{padding:5px 0;border-bottom:1.5px dotted #D3E9F7;background:none;border-radius:0}
.mg .detail-row i{display:none}
.mg .detail-label{font-family:var(--fc-cute);font-size:11.5px;font-weight:700;color:#5B87A6;letter-spacing:0}
.mg .detail-val{font-family:var(--fc-num);font-size:13px;font-weight:700;color:#0E3A57;letter-spacing:.2px}
.mg-cols{column-gap:18px;column-rule:1.5px dotted #DCEEF9}

/* ───── 引文：粉色圆角卡 ───── */
.mg-quote{margin:12px 12px 0;padding:12px 13px 11px 34px;border:none;border-radius:16px;background:#FFF7FB}
.mg-quote::before{left:9px;top:7px;font-family:var(--fc-cute);font-size:34px;line-height:1;color:#FF9EC8;opacity:.75}
.mg-quote .detail-block{border:none;background:none;padding:0;margin:0}
.mg-quote .detail-thought{font-family:var(--fc-cute);font-size:12.5px;font-style:normal;line-height:1.85;color:#3A5F7D;font-weight:500}
.mg-quote .detail-thought.empty{color:#9BB8CB}

/* ───── 页脚：青底虚线 ───── */
.mg-footer{margin-top:13px;padding:9px 16px;border-top:2px dashed #CFE7F6;background:#F2FAFF;
  font-family:var(--fc-num);font-size:10.5px;font-weight:700;letter-spacing:.6px;color:#7FA9C4}
.mg-footer span:last-child{color:#3FA9DC}

/* ════════ 状态栏主页：可爱元素 ════════ */
.home-card{border-radius:16px;border:2px solid #C7E7FA;border-left:2px solid #C7E7FA;padding:11px 13px;
  background:linear-gradient(150deg,#FBFEFF,#E9F6FF);box-shadow:0 6px 18px rgba(18,60,92,.28)}
.home-title{font-family:var(--fc-cute);font-size:12px;font-weight:900;letter-spacing:1px;color:#3FA9DC}
.home-title i{color:#8FD8F7}
.home-title::before{content:'\2727';margin-right:4px;color:#FFB7D5}
.home-world-line{font-family:var(--fc-cute);font-size:15px;font-weight:800;letter-spacing:0;color:#0E3A57}
.home-world-sub{color:#6C9AB8;font-size:11px;font-weight:600}
.home-world-sub span{color:#E4639F;font-family:var(--fc-num);font-weight:700}
.sense-row{font-size:12px;color:#2C5470;line-height:1.75}
.sense-row i{color:#3FA9DC}
.sense-label{font-family:var(--fc-cute);font-size:11.5px;font-weight:700;letter-spacing:0;color:#7FA9C4}
.home-net .net-item{font-size:12px;color:#2C5470;border-left:3px solid #8FD8F7;padding-left:13px;line-height:1.65}
.home-net .net-item::before{content:'\2665';color:#FF9EC8;left:1px;font-size:10px}
.home-net .net-viewport{height:46px}

/* 六个状态按钮：圆角小胶囊 */
.res-chip{border-radius:999px!important;border:2px solid #C7E7FA;background:#F7FCFF;
  padding:3px 10px 3px 4px!important;transition:transform .16s ease, box-shadow .16s ease}
.res-chip:hover{transform:translateY(-2px);box-shadow:0 6px 14px rgba(63,169,220,.28)}
.res-orb{border-radius:50%!important}
.res-chip span,.res-chip div:not(.res-orb){color:#0E3A57}
.res-chip i{color:#3FA9DC}

/* ───── 底部对话区 / 选项：圆润白卡 ───── */
.dialog-zone{background:linear-gradient(0deg,#EAF6FF 0%,#F7FCFF 62%,rgba(247,252,255,.55) 100%);border-top:3px solid #BFE4F8}
.dialog-scroll{border:2.5px solid #FFFFFF;border-radius:20px;padding:14px 16px 12px;
  background:#fff;box-shadow:0 6px 20px rgba(18,60,92,.18)}
.dialog-scroll::after{content:'FOOT HEAVEN';color:#A9D2E8;font-family:var(--fc-num);font-size:9px;letter-spacing:2px}
.speaker-glyph{width:46px;height:46px;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 3px #BFE4F8}
.speaker-name{font-family:var(--fc-cute);font-size:15px;font-weight:900;letter-spacing:.5px;color:#0E3A57;text-shadow:none}
.dialog-text{position:relative;padding-left:22px;border-left:none;font-size:13px;line-height:1.85;color:#1B3A57;font-family:var(--fc-cute);font-weight:500}
.dialog-text::before{content:'\201C';left:2px;top:-8px;font-size:30px;color:#FFB7D5}
.choices{gap:8px}
.choice-btn{border:2.5px solid #DDEEFA;border-left:2.5px solid #DDEEFA;border-radius:16px;padding:10px 14px;background:#fff;
  font-family:var(--fc-cute);font-size:13px;font-weight:700;color:#1B3A57;transition:transform .16s ease, border-color .16s ease}
.choice-btn::before{display:none}
.choice-btn:hover{transform:translateX(4px);border-color:#8FD8F7;background:#F4FBFF;box-shadow:0 4px 12px rgba(63,169,220,.18)!important}
.choice-rune{width:24px;height:24px;border-radius:50%;background:#FFF0F7;color:#FF9EC8;font-family:var(--fc-num);font-weight:800;text-shadow:none;
  display:flex;align-items:center;justify-content:center;font-size:12px}
.choice-meta{font-family:var(--fc-num);font-size:10px;font-weight:700;letter-spacing:.5px;color:#8FBFDA}
.input-zone{border:2.5px solid #CFEAFB;border-radius:18px;background:#fff}
.input-field{background:transparent!important;border:none!important;color:#1B3A57!important;font-family:var(--fc-cute);font-size:13px}
.cast-btn{border-radius:16px;background:linear-gradient(135deg,#8FD8F7,#3FA9DC)!important;font-family:var(--fc-cute);font-weight:800;letter-spacing:1px;color:#fff}
/* ════════ 可爱化修正：海报带清晰 + 白色名牌底衬 ════════ */
.nearby-detail.mg{
  background-image:
    linear-gradient(180deg,
      rgba(255,255,255,0) 0px,
      rgba(255,255,255,0) 132px,
      rgba(255,255,255,.52) 168px,
      rgba(245,251,255,.985) 198px,
      rgba(240,249,255,.985) 100%),
    var(--mg-poster, none),
    linear-gradient(180deg,#FFFFFF,#D9EEFB);
}
.mg-mast{left:12px;top:11px;color:#3FA9DC;border-left:none;background:rgba(255,255,255,.88);border-radius:12px;
  padding:5px 10px;text-shadow:none;box-shadow:0 3px 10px rgba(18,60,92,.16)}
.mg-cover-txt{left:12px;right:72px;bottom:10px;background:rgba(255,255,255,.93);border-radius:15px;padding:8px 12px;
  box-shadow:0 4px 14px rgba(18,60,92,.14)}
.mg-name{color:#0E3A57;text-shadow:none}
.mg-issue{color:#3FA9DC}
.mg-subline{color:#5B87A6}
.mg-crop{display:none}
@media (max-width:520px){
  .mg-name{font-size:24px}
  .mg-stats{grid-template-columns:repeat(2,1fr)}
}
/* ════════ v4：主色青 / 辅色粉 + 因特网跑马灯 + SillyTavern/手机竖屏适配 ════════ */

/* ── ① 配色：紫 → 青，金 → 青/粉 ── */
:root{
  --void:#07131F; --abyss:#0A1B2B; --night:#0F2436;
  --gold:#3FA9DC; --gold-bright:#5BC0E8; --gold-deep:#2E86B8;
  --violet:#3FA9DC; --violet-bright:#5BC0E8;
  --aqua:#3FA9DC; --aqua-bright:#5BC0E8;
  --rose:#FF7FB6; --crimson:#FF5C8A;
  --wht:#F2FAFF; --dim:#8AB4CE; --muted:#5E8199;
  --line:rgba(143,216,247,.30); --line-soft:rgba(255,255,255,.10);
  --rune-bg:rgba(63,169,220,.08);
  --grad-gold:linear-gradient(135deg,#2E86B8 0%,#3FA9DC 50%,#8FD8F7 100%);
  --grad-aqua:linear-gradient(135deg,#1A5A6E 0%,#3FA9DC 100%);
  --grad-violet:linear-gradient(135deg,#2E86B8 0%,#8FD8F7 100%);
  --grad-portal:radial-gradient(circle,#3FA9DC 0%,#2E86B8 40%,#0A1B2B 100%);
  --grad-hero:linear-gradient(180deg,transparent 0%,rgba(10,27,43,.9) 70%,var(--void) 100%);
  --pv-star:#FF7FB6; --pv-mag:#FF7FB6; --pv-cyan:#8FD8F7; --pv-line:rgba(143,216,247,.42);
  --pv-paper:#BFE4F8;
}
body{background:
  radial-gradient(ellipse 62% 48% at 16% 18%, rgba(63,169,220,.30) 0%, transparent 62%),
  radial-gradient(ellipse 58% 46% at 88% 82%, rgba(255,127,182,.22) 0%, transparent 64%),
  linear-gradient(165deg,#071726 0%,#0A1020 48%,#0E1F35 100%)!important}
#nebula{background:
  radial-gradient(ellipse 60% 50% at 20% 30%, rgba(63,169,220,.26) 0%, transparent 60%),
  radial-gradient(ellipse 50% 40% at 80% 70%, rgba(143,216,247,.16) 0%, transparent 60%),
  radial-gradient(ellipse 40% 30% at 50% 90%, rgba(255,127,182,.14) 0%, transparent 60%)!important}
#rune-circle{border-color:rgba(143,216,247,.10)!important}
#rune-circle::before{border-color:rgba(143,216,247,.12)!important}
#rune-circle::after{border-color:rgba(255,127,182,.10)!important}
#app{
  border:10px solid var(--pv-paper)!important;
  background:
    radial-gradient(rgba(255,255,255,.05) 1px, transparent 1.4px) 0 0/7px 7px,
    radial-gradient(120% 80% at 80% 16%, rgba(255,127,182,.16) 0%, transparent 56%),
    radial-gradient(120% 90% at 10% 90%, rgba(63,169,220,.20) 0%, transparent 55%),
    linear-gradient(160deg,#081A2B 0%,#0A1220 46%,#102338 100%)!important;
}
.brand-title{color:#fff!important;text-shadow:0 0 14px rgba(143,216,247,.8),0 0 26px rgba(255,127,182,.45)!important}
.brand-sub{color:#FF9EC8!important}
.pv-title-main{text-shadow:0 2px 18px rgba(143,216,247,.6),0 0 30px rgba(255,127,182,.35)!important}
.pv-title-sub{color:#8FD8F7!important}
.pv-chips .res-chip:hover{border-color:#8FD8F7!important;background:rgba(143,216,247,.14)!important;box-shadow:0 0 14px rgba(143,216,247,.35)!important}

/* ── ② 因特网：顶部跑马灯 ── */
.home-net{min-width:0;overflow:hidden}
.home-net .net-viewport{position:relative;width:100%;max-width:100%;box-sizing:border-box;height:34px;
  overflow:hidden;border-radius:999px;margin-top:3px;background:#EEF8FF;border:2px solid #CFEAFB;padding:0 4px}
.home-net #homeNetBox{width:100%;max-width:100%;height:100%;overflow:hidden}
.home-net .net-track{display:flex;align-items:center;height:100%;white-space:nowrap;
  animation:netMarquee 24s linear infinite;will-change:transform}
.home-net .net-group{display:inline-flex;align-items:center;flex:0 0 auto;height:100%}
.home-net .net-line{display:inline-block;flex:0 0 auto;font-size:12px;font-weight:600;color:#2C5470;
  padding:0 14px;line-height:34px;font-family:var(--fc-cute)}
.home-net .net-sep{flex:0 0 auto;color:#FF9EC8;font-size:9px}
.home-net .net-item.dim{font-size:12px;color:#8FBFDA;line-height:34px;padding-left:10px}
@keyframes netMarquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}
@media (hover:hover) and (pointer:fine){
  .home-net .net-viewport:hover .net-track{animation-play-state:paused}
}

/* ── ③ SillyTavern / 手机竖屏适配 ── */
html,body{max-width:100%;overflow-x:hidden;box-sizing:border-box}
#app{height:auto!important;min-height:0!important;grid-template-rows:auto auto auto!important;grid-template-columns:minmax(0,1fr)!important}
.stage,.compass-stage{min-width:0!important;max-width:100%!important}
.home-panel,.home-card,.home-net,.net-viewport,#homeNetBox{min-width:0!important}
@media (max-width:560px){
  #app{border-width:6px!important;border-radius:2px!important}
  .top-bar{padding:8px 10px!important;gap:6px!important;flex-wrap:wrap!important}
  .brand-sigil{width:28px!important;height:28px!important}
  .brand-title{font-size:15px!important;letter-spacing:1px!important}
  .brand-sub{font-size:9px!important;letter-spacing:1px!important}
  .pv-title{display:none!important}
  .status-rings,.pv-chips{width:100%!important;margin-left:0!important;justify-content:flex-start!important;gap:5px!important}
  .pv-chips .res-chip{padding:3px 9px 3px 4px!important}
