/* ════════ v5：去紫（纯青粉背景）+ 左侧竖排刊名 ════════ */
body{background:
  radial-gradient(ellipse 62% 48% at 14% 16%, rgba(63,169,220,.34) 0%, transparent 62%),
  radial-gradient(ellipse 50% 40% at 90% 86%, rgba(255,127,182,.15) 0%, transparent 64%),
  linear-gradient(168deg,#06202F 0%,#08192A 50%,#0B2436 100%)!important}
#nebula{background:
  radial-gradient(ellipse 60% 50% at 18% 28%, rgba(63,169,220,.30) 0%, transparent 62%),
  radial-gradient(ellipse 48% 38% at 84% 74%, rgba(143,216,247,.16) 0%, transparent 60%),
  radial-gradient(ellipse 34% 26% at 52% 94%, rgba(255,127,182,.09) 0%, transparent 62%)!important}
#app{
  background:
    radial-gradient(rgba(255,255,255,.05) 1px, transparent 1.4px) 0 0/7px 7px,
    radial-gradient(110% 70% at 88% 8%, rgba(143,216,247,.15) 0%, transparent 58%),
    radial-gradient(120% 90% at 6% 92%, rgba(63,169,220,.22) 0%, transparent 56%),
    linear-gradient(160deg,#08202F 0%,#0A1726 46%,#0E2A3C 100%)!important;
}
/* 紫色主来源：立绘光晕的洋红 → 全改青 */
.pv-hero-burst{background:radial-gradient(circle at 68% 42%, rgba(143,216,247,.30) 0%, rgba(63,169,220,.14) 36%, transparent 72%)!important}
.pv-vertical{color:rgba(208,238,255,.52)!important}
.pv-code{color:rgba(186,222,244,.5)!important}
.pv-cell{border-color:rgba(143,216,247,.4)!important}
.pv-cell span{color:#8FD8F7!important}
.pv-eq i{background:linear-gradient(180deg,#8FD8F7,#FF9EC8)!important}

/* ── 左侧竖排刊名栏 ── */
.pv-title{position:absolute!important;left:10px;top:50%;transform:translateY(-50%);z-index:6;
  display:flex!important;flex-direction:row;align-items:center;gap:12px;
  padding:14px 9px;border:none!important;border-radius:18px;
  background:linear-gradient(180deg,rgba(143,216,247,.18),rgba(255,127,182,.13));
  box-shadow:0 8px 22px rgba(6,32,47,.5)}
.pv-title-main{writing-mode:vertical-rl;text-orientation:upright;
  font-family:var(--fc-cute);font-weight:900;font-size:17px;letter-spacing:7px;
  color:#fff;line-height:1;text-shadow:0 0 14px rgba(143,216,247,.85)}
.pv-title-sub{writing-mode:vertical-rl;text-orientation:mixed;margin:0;font-style:normal;
