.compass-stage{padding-left:62px!important}
.pv-code{left:64px!important}
.pv-eq{left:64px!important}

@media (max-width:560px){
  /* 手机端保留杂志装饰：缩到边缘当点缀，不遮内容 */
  .pv-code{display:block!important;left:44px!important;top:6px!important;font-size:8px!important;opacity:.45}
  .pv-eq{display:flex!important;left:44px!important;bottom:6px!important;height:15px!important;opacity:.65;
    transform:scale(.78);transform-origin:bottom left}
  .pv-collage{display:flex!important;flex-direction:row!important;top:auto!important;bottom:6px!important;right:4px!important;
    gap:5px!important;z-index:5;opacity:.92;pointer-events:none;transform:scale(.66);transform-origin:bottom right}
