<script>
(function(){
'use strict';
__dbg('IIFE_START',{ts:Date.now()});

/* 图片加载失败时隐藏元素，回退到SVG/渐变 */
function imgErr(img){img.style.display='none';if(img.parentNode&&img.parentNode.classList.contains('has-img'))img.parentNode.classList.remove('has-img')}

/* #region debug-point INSTRUMENT */
/* 调试日志上报器（运行时证据收集） */
var __DBG_URL='http://127.0.0.1:7778/event';
var __DBG_SID='button-click-broken';
function __dbg(point,extra){
  try{
    var payload={session:__DBG_SID,point:point,ts:Date.now(),url:location.href,extra:extra||{}};
    if(navigator&&navigator.sendBeacon){
      var fd=new FormData();fd.append('payload',JSON.stringify(payload));navigator.sendBeacon(__DBG_URL,fd);
    }else{
      var x=new XMLHttpRequest();x.open('POST',__DBG_URL,true);x.setRequestHeader('Content-Type','application/json');x.send(JSON.stringify(payload));
    }
  }catch(e){}
}
/* 全局错误捕获 */
window.addEventListener('error',function(e){__dbg('GLOBAL_ERROR',{msg:String(e.message),filename:e.filename,lineno:e.lineno,colno:e.colno,stack:e.error&&e.error.stack?String(e.error.stack):''})});
window.addEventListener('unhandledrejection',function(e){__dbg('UNHANDLED_REJECTION',{reason:String(e.reason)})});
__dbg('SCRIPT_START',{readyState:document.readyState});
/* #endregion debug-point INSTRUMENT */

/* 角色名 → 头像URL 映射（用于附近角色动态渲染） */
const charImgMap={};

/* ════════ 星空背景 ════════ */
const canvas=document.getElementById('starfield');
const ctx=canvas.getContext('2d');
let stars=[],w,h,dpr=1;
var rafId=null,lastTime=0,isVisible=true;
var isMobile=window.innerWidth<820||('ontouchstart' in window);
function resize(){
  /* 限制DPR：手机端用1.0避免过度渲染，PC端最高1.5 */
  dpr=Math.min(window.devicePixelRatio||1, isMobile?1:1.5);
  w=window.innerWidth;
  h=window.innerHeight;
  canvas.width=Math.floor(w*dpr);
  canvas.height=Math.floor(h*dpr);
  canvas.style.width=w+'px';
  canvas.style.height=h+'px';
  ctx.setTransform(dpr,0,0,dpr,0,0);
  stars=[];
  /* 手机端粒子数大幅减少：≤60；PC端≤120（原180） */
  var density=isMobile?26000:13000;
  var cap=isMobile?60:120;
  var n=Math.min(cap,Math.floor(w*h/density));
  for(var i=0;i<n;i++){
    stars.push({
      x:Math.random()*w,
      y:Math.random()*h,
      r:Math.random()*1.2+0.3,
      a:Math.random()*0.6+0.2,
      tw:Math.random()*0.02+0.005,
      ph:Math.random()*Math.PI*2,
      c:Math.random()<0.15?'244,200,66':(Math.random()<0.3?'157,108,255':'232,232,255')
    });
  }
}
function draw(ts){
  if(!isVisible){return;}
  /* 限帧约30fps，降低一半绘制开销 */
  if(ts-lastTime<33){rafId=requestAnimationFrame(draw);return;}
  lastTime=ts;
  ctx.clearRect(0,0,w,h);
  for(const s of stars){
    s.ph+=s.tw;
    const a=s.a*(0.6+0.4*Math.sin(s.ph));
    ctx.beginPath();
    ctx.arc(s.x,s.y,s.r,0,Math.PI*2);
    ctx.fillStyle='rgba('+s.c+','+a+')';
    ctx.fill();
    /* 仅较大星绘制光晕，且半径收窄 */
    if(s.r>1.1){
      ctx.beginPath();
      ctx.arc(s.x,s.y,s.r*1.8,0,Math.PI*2);
      ctx.fillStyle='rgba('+s.c+','+(a*0.15)+')';
      ctx.fill();
    }
  }
  rafId=requestAnimationFrame(draw);
}
/* 全局关闭 Canvas 星空动画（PC+手机），省去 RAF 与绘制开销 */
/* resize/draw 函数保留供调试，但不启动任何循环 */
if(false && !isMobile){
  resize();
  rafId=requestAnimationFrame(draw);
  window.addEventListener('resize',resize);
  /* 页面隐藏时暂停动画，避免后台占用 */
  document.addEventListener('visibilitychange',function(){
    isVisible=!document.hidden;
    if(!isVisible&&rafId){cancelAnimationFrame(rafId);rafId=null;}
    else if(isVisible&&!rafId){rafId=requestAnimationFrame(draw);}
  });
}

