var __homeNetTimer=null, __homeNetIdx=0;
function renderHomeCarousel(){
  var box=document.getElementById('homeNetBox');
  if(!box)return;
  var paths=['因特网.公司主播推特1','因特网.公司主播推特2','因特网.竞争对手主播推特3','因特网.竞争对手主播推特4'];
  var items=[];
  for(var i=0;i<paths.length;i++){var v=eraGet(paths[i],'');if(v&&String(v).trim())items.push(String(v));}
  if(__homeNetTimer){clearInterval(__homeNetTimer);__homeNetTimer=null;}
  __homeNetIdx=0;
  if(!items.length){box.innerHTML='<div class="net-item dim">暂无动态</div>';return;}
  /* 跑马灯：先测单组宽，再按视口宽度复制成「两份完全相同的大组」实现无缝循环 */
  var _sep='<span class="net-sep">\u2726</span>';
  var _one=items.map(function(s){return '<span class="net-line">'+s+'</span>';}).join(_sep)+_sep;
  box.innerHTML='<div class="net-track"><span class="net-group">'+_one+'</span></div>';
  var _track=box.querySelector('.net-track');
  var _grp=box.querySelector('.net-group');
  if(_track&&_grp){
    var _gw=_grp.getBoundingClientRect().width||_grp.scrollWidth||1;
    var _vw=Math.min(box.getBoundingClientRect().width||320,1200);
    var _rep=Math.max(1,Math.ceil(_vw/_gw));
    var _big='';
    for(var _i=0;_i<_rep;_i++){_big+=_one;}
    _track.innerHTML='<span class="net-group">'+_big+'</span><span class="net-group">'+_big+'</span>';
    var _bw=_track.firstElementChild.getBoundingClientRect().width||(_gw*_rep);
    _track.style.animationDuration=Math.max(9,Math.round(_bw/120))+'s';
  }
  if(!window.__netResizeBound){
    window.__netResizeBound=1;
    window.addEventListener('resize',function(){clearTimeout(window.__netRz);window.__netRz=setTimeout(function(){try{renderHomeCarousel();}catch(e){}},300);});
  }
}

