  var out=[];
  for(var i=0;i<pref.length;i++){ if(all.indexOf(pref[i])>=0) out.push(pref[i]); }
  for(var j=0;j<all.length;j++){ if(out.indexOf(all[j])<0) out.push(all[j]); }
  if(!out.length) out=['\u5fae\u7b11','\u5bb3\u7f9e','\u5f00\u5fc3'];
  while(n>0&&out.length<n) out=out.concat(out);
  return out;
}
/* 从可用表情里不重复地随机取 n 个（活泼不重样） */
function mgRandPick(arr,n){
  var a=(arr||[]).slice(), out=[];
  n=Math.min(n, a.length);
  for(var i=0;i<n;i++){ out.push(a.splice(Math.floor(Math.random()*a.length),1)[0]); }
  return out;
}
/* 头图表情：每次随机 */
function mgHeroScene(){ var l=mgSceneList(1); return l[Math.floor(Math.random()*l.length)]; }
var __heroIdx=0, __heroLast=-1;
/* 23 \u4f4d\u4e3b\u64ad\u300c\u5168\u968f\u673a\u300d\u8f6e\u64ad\uff1a\u5215\u53f7\u540d + \u5927\u7acb\u7ed8 + \u4e09\u5f20\u62fc\u8d34\u56fe\u540c\u6b65\u6362\u4eba */
function renderHomeHero(){
  var _list=mgHeroList();
  if(!_list||!_list.length)return;
  var _n=_list.length,_i=0;
  if(_n>1){ do{ _i=Math.floor(Math.random()*_n); }while(_i===__heroLast); }
  __heroLast=_i; __heroIdx=_i;
  var name=_list[_i];
  var nameEl=document.getElementById('pvHeroName');
  if(nameEl){
    nameEl.textContent=name;
    var _L=(name||'').length;
    nameEl.style.fontSize=(_L>=6?'12px':(_L>=5?'14px':'17px'));
  }
  var img=document.getElementById('pvHeroImg');
  if(img){
    img.onload=function(){this.style.opacity=1;};
    img.style.opacity=1;
    img.src=mgUrl(name,'SFW',mgHeroScene(),1);
  }
  var _cells=document.querySelectorAll('.pv-collage .pv-cell img');
  var _scenes=mgRandPick(mgSceneList(3),3);
  while(_scenes.length<3){ _scenes.push(_scenes[Math.floor(Math.random()*_scenes.length)]); }
  for(var k=0;k<_cells.length;k++){
    _cells[k].style.display='';
    _cells[k].src=mgUrl(name,'SFW',_scenes[k%_scenes.length],1);
  }
}
/* \u5e42\u7b49\u542f\u52a8\u5668\uff1a\u65e0\u8bba onload \u8fd8\u662f\u9152\u9986\u6ce8\u5165\uff0c\u90fd\u80fd\u628a 20 \u79d2\u8f6e\u64ad\u5f00\u8d77\u6765 */
function renderHeroBoot(){
  try{ if(!window.__heroBooted){window.__heroBooted=1;renderHomeHero();} }catch(e){}
  try{ if(!window.__heroTimer){window.__heroTimer=setInterval(function(){try{renderHomeHero();}catch(e){}},600000);} }catch(e){}
}

