      '</div>'+
      '<div class="mg-barcode"></div>'+
    '</div>';

  var html='<div class="nearby-detail mg" style="--mg-poster:url(\''+_poster+'\')">'+
    cover+
    '<div class="mg-lead">'+info.desc+'</div>'+
    '<div class="mg-sec"><div class="mg-sec-h"><span>DATA</span>\u5f53\u524d\u6570\u503c</div>'+rows+'</div>'+
    '<div class="mg-footer"><span>FOOT HEAVEN \u00b7 DATA FILE</span><span>'+info.title+' \u00b7 P.'+mgPad2(_oi+1)+'</span></div>'+
    '</div>';

  var layer=document.getElementById('statInfoLayer');
