// ==================== ERA 监听 ====================
function setupERAListeners() {
    // 确保 eventOn / eventEmit 存在（酒馆助手环境）
    if (typeof eventOn === 'undefined') {
        console.warn("⚠️ eventOn 未定义，请确认在酒馆助手环境中运行");
        return;
    }

    eventOn('era:writeDone', (detail) => {
        console.log('%c[ERA] writeDone', 'color:#67e8f9', detail);
        if (detail.statWithoutMeta) {
            renderAll(detail.statWithoutMeta);
        }
        /* CG画廊：ERA写入后扫描聊天记录解锁新CG */
        setTimeout(function(){cgScanChat();},300);
    });

    eventOn('era:queryResult', (detail) => {
        if (detail.result && detail.result.error) {
            console.error('ERA 查询失败:', detail.result.error);
            return;
        }
        if (detail.queryType === 'getCurrentVars' && detail.result) {
            renderAll(detail.result.statWithoutMeta || detail.result.stat);
        }
    });

    // 初始化获取一次数据
    setTimeout(() => {
        if (typeof eventEmit === 'function') {
            eventEmit('era:getCurrentVars');
        }
    }, 1200);
}

// ==================== 初始化 ====================
window.__homeInit = function() {
    if(window.__homeInitDone)return;
    window.__homeInitDone=1;
    setupERAListeners();
    renderHomeCarousel();   // 初始化主页·因特网轮播
    renderHomeHero();       // 初始化杂志主视觉
    renderHeroBoot();                       /* 20 秒随机轮播 */
    /* CG画廊：初始化扫描 + 定时扫描酒馆聊天 */
    setTimeout(function(){cgScanChat();},2000);
    setInterval(function(){if(document.hidden)return;cgScanChat();},15000);
    /* CG画廊：MutationObserver 实时监听新消息（参考 loveli 状态栏机制） */
    (function(){
      var __cgPending=false;
      var __cgObserver=new MutationObserver(function(mutations){
        if(__cgPending)return;                       /* 节流：避免密集重复扫描 */
        var hit=false;
        for(var mi=0;mi<mutations.length&&!hit;mi++){
          var add=mutations[mi].addedNodes;
          for(var ai=0;ai<add.length;ai++){
            var node=add[ai];
            if(node.nodeType===3){
              var tv=node.nodeValue||'';
              if(tv.indexOf('SFW/')>=0||tv.indexOf('NSFW/')>=0||tv.indexOf('<img>')>=0||tv.indexOf('&lt;img&gt;')>=0){hit=true;break;}
            }else if(node.nodeType===1){
              /* 不再对整棵子树做 textContent（O(n) 字符串分配，流式输出时是主卡顿源）→ 改用原生选择器 */
              if(node.tagName==='IMG'||node.tagName==='VIDEO'){hit=true;break;}
              if(node.querySelector&&node.querySelector('img[src*="SFW/"],img[src*="NSFW/"]')){hit=true;break;}
            }
          }
        }
        if(hit){
          __cgPending=true;
          setTimeout(function(){ __cgPending=false; try{cgScanChat();}catch(e){} },400);
        }
      });
      __cgObserver.observe(document.body,{childList:true,subtree:true});
      /* 同时监听父文档（酒馆主界面） */
      try{
        if(window.parent&&window.parent.document&&window.parent.document!==document){
          __cgObserver.observe(window.parent.document.body,{childList:true,subtree:true});
        }
      }catch(e){}
    })();
    document.addEventListener('keydown',function(e){
      if(e.key==='Escape'){
        var fs=document.getElementById('cgFsOverlay');
        var modal=document.getElementById('cgModalOverlay');
        if(fs&&fs.classList.contains('active')){cgCloseFs();return;}
        if(modal&&modal.classList.contains('active')){cgCloseCharModal();return;}
      }
    });
    /* CG 弹窗背景点击关闭 */
    var __cgModal=document.getElementById('cgModalOverlay');
    if(__cgModal)__cgModal.addEventListener('click',function(e){if(e.target===__cgModal)cgCloseCharModal();});
    var __cgFs=document.getElementById('cgFsOverlay');
    if(__cgFs)__cgFs.addEventListener('click',function(e){if(e.target===__cgFs)cgCloseFs();});
    console.log("%c🌌 足控天堂 Ⅱ · 城市地图 + ERA 监听 已加载", "color:#F4C842; font-weight:bold; font-size:14px");
};
/* 关键：酒馆/iframe 是在页面 load 之后才注入状态栏的，window.onload 不会再触发 → 立即执行 */
if(document.readyState==='complete'||document.readyState==='interactive'){
  setTimeout(window.__homeInit,0);
}else{
  window.addEventListener('DOMContentLoaded',window.__homeInit);
  window.addEventListener('load',window.__homeInit);
}
</script>

